COPY_TRADING_TEMPLATE = """
<!DOCTYPE html>
<html lang="tr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Copy Trading | AU Auto Trade</title>
    <style>
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { 
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; 
            background: #0f0f0f; 
            color: #fff; 
            min-height: 100vh; 
        }
        #sidebar { position: fixed; left: 0; top: 0; height: 100vh; width: 256px; background: #1a1a1a; border-right: 1px solid rgba(255,255,255,0.1); z-index: 100; overflow-y: auto; }
        .content { margin-left: 256px; padding: 24px; min-height: 100vh; }
        h1 { font-size: 28px; margin-bottom: 8px; }
        .subtitle { color: #9ca3af; font-size: 14px; margin-bottom: 24px; }
        .card { padding: 18px; border-radius: 16px; background: #1a1a1a; border: 1px solid rgba(255,255,255,0.1); }
        @media (max-width: 1024px) { 
            #sidebar { display: none; } 
            .content { margin-left: 0; padding: 16px; }
        }
    </style>
</head>
<body>
{{ sidebar | safe }}
<div class="content">
<h1>Copy Trading</h1>
<p class="subtitle">Profesyonel traderları takip edin ve işlemlerini kopyalayın</p>

<div class="card" style="padding:18px; border-radius:16px; background:#1a1a1a; border:1px solid rgba(255,255,255,0.1);">
  <div style="display:flex; gap:16px; align-items:flex-start; flex-wrap:wrap;">
    <div style="flex:1; min-width:320px;">
      <div style="font-weight:700; font-size:18px; margin-bottom:10px; color:white;">Başarılı Traderlar</div>
      <div id="auTopTraders" style="display:flex; flex-direction:column; gap:10px;"></div>
    </div>

    <div style="flex:2; min-width:420px;">
      <div style="font-weight:700; font-size:18px; margin-bottom:10px; color:white;">Canlı Akış</div>
      <div id="auLiveFeed" style="display:flex; flex-direction:column; gap:10px; max-height:520px; overflow:auto;"></div>
    </div>
  </div>
  
  <div style="margin-top:14px;">
    <div style="font-weight:700; font-size:16px; margin-bottom:10px; color:white;">
      Seçili Trader Açık Pozisyonlar
    </div>
    <div id="auPositions" style="display:flex; flex-direction:column; gap:10px; max-height:260px; overflow:auto;"></div>
    <div id="auPositionsEmpty" style="opacity:.70; font-size:12px; padding:10px 12px; border:1px solid rgba(255,255,255,0.08); border-radius:12px; display:none; color:#aaa;">
      Pozisyon bulunamadı
    </div>
  </div>
</div>

</div>
</div>
</div>

<script>
(function(){
  const topEl = document.getElementById("auTopTraders");
  const feedEl = document.getElementById("auLiveFeed");
  const posEl  = document.getElementById("auPositions");
  const posEmptyEl = document.getElementById("auPositionsEmpty");

  let currentUC = "";

  function fmtPct(x){
    try { return (Number(x)*100).toFixed(1) + "%"; } catch(e){ return String(x); }
  }
  function fmtTs(ts){
    const d = new Date((Number(ts)||0)*1000);
    const hh = String(d.getHours()).padStart(2,"0");
    const mm = String(d.getMinutes()).padStart(2,"0");
    const ss = String(d.getSeconds()).padStart(2,"0");
    return `${hh}:${mm}:${ss}`;
  }

  function setSelectedRow(uc){
    currentUC = uc || "";
    [...topEl.querySelectorAll("[data-uc]")].forEach(el => {
      el.style.borderColor = (el.getAttribute("data-uc") === currentUC)
        ? "rgba(0,255,120,0.35)"
        : "rgba(255,255,255,0.08)";
    });
  }

      function loadPositions(){
        if(!currentUC) return;
        fetch("/api/copy/positions?uniqueCode="+encodeURIComponent(currentUC), {credentials:"include"})
        .then(r=>r.json())
        .then(j=>{
          const arr = j.items || j.positions || [];
          posEmptyEl.style.display = arr.length ? "none" : "block";
          posEl.innerHTML = "";
          arr.forEach(p=>{
            const pnlColor = (p.pnl||0) >= 0 ? "#22c55e" : "#ef4444";
            const sideColor = p.side === "LONG" ? "#22c55e" : "#ef4444";
            const sideBg = p.side === "LONG" ? "rgba(34,197,94,0.15)" : "rgba(239,68,68,0.15)";
            const d = document.createElement("div");
            d.style.cssText = "padding:14px;border-radius:12px;border:1px solid rgba(255,255,255,0.08);background:#1a1a1a;margin-bottom:10px;";
            d.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">'+
              '<div><span style="font-weight:700;font-size:16px;color:white;">'+p.symbol+'</span>'+
              '<span style="margin-left:8px;padding:2px 8px;border-radius:6px;font-size:12px;font-weight:600;color:'+sideColor+';background:'+sideBg+';">'+p.side+'</span>'+
              '<span style="margin-left:6px;padding:2px 6px;border-radius:4px;font-size:11px;color:#94a3b8;background:rgba(255,255,255,0.05);">'+String(p.leverage||"1x")+'</span></div>'+
              '<div style="text-align:right;"><div style="color:'+pnlColor+';font-weight:700;font-size:15px;">$'+Number(p.pnl||0).toFixed(2)+'</div>'+
              '<div style="color:'+pnlColor+';font-size:12px;">'+Number(p.pnl_pct||0).toFixed(2)+'%</div></div></div>'+
              '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:13px;margin-bottom:12px;">'+
              '<div><span style="color:#6b7280;">Giris:</span> <span style="color:white;font-weight:600;">$'+Number(p.entry_price||0).toFixed(p.entry_price>100?2:4)+'</span></div>'+
              '<div><span style="color:#6b7280;">Guncel:</span> <span style="color:white;font-weight:600;">$'+Number(p.current_price||0).toFixed(p.current_price>100?2:4)+'</span></div>'+
              '<div><span style="color:#6b7280;">Miktar:</span> <span style="color:white;">$'+Number(p.size_usdt||0).toFixed(0)+' USDT</span></div>'+
              '<div><span style="color:#6b7280;">Borsa:</span> <span style="color:white;">'+String(p.exchange||"OKX")+'</span></div></div>'+
              '<button onclick="manuelAl(&#39;'+p.symbol+'&#39;,'+Number(p.current_price||0).toFixed(p.current_price>100?2:4)+',&#39;'+p.side+'&#39;)" '+
              'style="width:100%;padding:10px;border-radius:10px;border:none;background:linear-gradient(135deg,#22c55e,#16a34a);color:white;font-weight:700;font-size:14px;cursor:pointer;transition:all 0.3s;">'+
              '\ud83d\uded2 Manuel Al ($'+Number(p.current_price||0).toFixed(p.current_price>100?2:4)+')</button>';
            posEl.appendChild(d);
          });
        })
        .catch(e=>{ console.warn("[CopyTrade] Pozisyon hatasi:", e); });
      }

      // Manuel satin alma fonksiyonu
      window.manuelAl = async function(symbol, price, side) {
        const v = prompt("USDT miktari girin (min 10):", "50");
        if(v===null) return;
        const amt = Number(String(v).replace(",", "."));
        if(!isFinite(amt) || amt<10){ alert("Minimum 10 USDT giriniz"); return; }
        try{
          const r = await fetch("/api/copy/manual_buy", {
            method:"POST", headers:{"Content-Type":"application/json"}, credentials:"include",
            body: JSON.stringify({symbol: symbol, amount_usdt: amt, price: price, side: side})
          });
          const j = await r.json().catch(()=>null);
          if(j && j.ok){ alert("\u2705 " + symbol + " " + amt + " USDT ile $" + price + " fiyatindan alindi!"); }
          else { alert((j&&(j.message||j.error||j.detail)) || "Islem basarisiz"); }
        }catch(e){ alert("Baglanti hatasi"); }
      };

  async function loadTop(){
    try {
      const r = await fetch("/api/copy/top", {credentials:"include"});
      const j = await r.json();
      if(!j || !j.ok) return;

      topEl.innerHTML = "";
      j.items.forEach((t, idx) => {
        const row = document.createElement("div");
        row.setAttribute("data-uc", t.uniqueCode || t.name || "");
        row.style.cssText = "display:flex; justify-content:space-between; gap:12px; padding:10px 12px; border:1px solid rgba(255,255,255,0.08); border-radius:12px; cursor:pointer; background:rgba(255,255,255,0.05);";
        row.innerHTML = `
          <div style="display:flex; flex-direction:column;">
            <div style="font-weight:700; color:white;">${idx+1}. ${t.name}</div>
            <div style="opacity:.75; font-size:12px; color:#aaa;">Takipçi ${t.followers || 0}</div>
          </div>
          <div style="display:flex; flex-direction:column; align-items:flex-end;">
            <div style="font-weight:700; color:#4ade80;">Win ${fmtPct(t.winRate ?? t.win_rate)}</div>
            <div style="opacity:.75; font-size:12px; color:#aaa;">ROI ${fmtPct(t.roi ?? t.roi_30d)}</div>
          </div>
        `;

        row.onclick = () => {
          const uc = row.getAttribute("data-uc") || "";
          setSelectedRow(uc);
          loadPositions();
        };

        topEl.appendChild(row);
      });

      if(!currentUC && j.items && j.items.length){
        const firstUC = j.items[0].uniqueCode || "";
        setSelectedRow(firstUC);
        loadPositions();
      } else {
        setSelectedRow(currentUC);
      }
    } catch(e) { console.error("loadTop error:", e); }
  }

  function pushFeedCard(item){
    const card = document.createElement("div");
    card.style.cssText = "padding:10px 12px; border:1px solid rgba(255,255,255,0.08); border-radius:12px; display:flex; justify-content:space-between; gap:12px; background:rgba(255,255,255,0.03);";
    const side = (item.side || "").toUpperCase();
    const badge = side === "BUY" ? "<span style='color:#4ade80;'>🟢 BUY</span>" : (side === "SELL" ? "<span style='color:#ef4444;'>🔴 SELL</span>" : "⚪️");
    card.innerHTML = `
      <div style="display:flex; flex-direction:column; gap:2px;">
        <div style="font-weight:700; color:white;">${badge} • ${item.symbol || "-"}</div>
        <div style="opacity:.78; font-size:12px; color:#aaa;">${item.trader || "-"} • ${item.source || "-"}</div>
      </div>
      <div style="display:flex; flex-direction:column; align-items:flex-end; gap:2px;">
        <div style="font-weight:700; color:white;">${(item.price!=null)?item.price:"-"}</div>
        <div style="opacity:.78; font-size:12px; color:#aaa;">${(item.size_usdt!=null)?(item.size_usdt+" USDT"):"-"} • ${fmtTs(item.ts)}</div>
      </div>
    `;
    feedEl.prepend(card);
    while(feedEl.children.length > 60){
      feedEl.removeChild(feedEl.lastChild);
    }
  }

  function startStream(){
    const es = new EventSource("/api/copy/stream");
    es.addEventListener("snapshot", (ev) => {
      try {
        const j = JSON.parse(ev.data || "{}");
        const items = (j.items || []).slice().reverse();
        feedEl.innerHTML = "";
        items.forEach(pushFeedCard);
      } catch(e){}
    });
    es.addEventListener("tick", (ev) => {
      try { pushFeedCard(JSON.parse(ev.data || "{}")); } catch(e){}
    });
    es.onerror = () => {
      try { es.close(); } catch(e){}
      setTimeout(startStream, 2000);
    };
  }

  loadTop();
  startStream();
  setInterval(loadTop, 60000);
  setInterval(loadPositions, 5000);
})();
</script>
</body>
</html>
"""

