@app.get("/api/chat_poll")
def api_chat_poll():
    # Chat GET: UI polling (room + since_id)
    try:
        since_id = int(request.args.get("since_id") or request.args.get("since") or 0)
    except Exception:
        since_id = 0

    room_id = normalize_room(request.args.get("room") or request.args.get("room_id") or "general")

    conn = db()
    try:
        room_expr = "COALESCE(c.room, c.room_id, 'general')"

        if since_id <= 0:
            # ilk yükleme: SON 200
            if room_id == "general":
                rows = conn.execute(f"""
                    SELECT c.id,
                           COALESCE(u.display_name, c.username) as username,
                           c.message,
                           c.created_at,
                           {room_expr} as room
                    FROM chat_messages c
                    LEFT JOIN users u ON c.username = u.username
                    ORDER BY c.id DESC
                    LIMIT 200
                """).fetchall()
            else:
                rows = conn.execute(f"""
                    SELECT c.id,
                           COALESCE(u.display_name, c.username) as username,
                           c.message,
                           c.created_at,
                           {room_expr} as room
                    FROM chat_messages c
                    LEFT JOIN users u ON c.username = u.username
                    WHERE lower({room_expr}) = lower(?)
                    ORDER BY c.id DESC
                    LIMIT 200
                """, (room_id,)).fetchall()

            msgs = [dict(r) for r in rows][::-1]
        else:
            # normal polling
            if room_id == "general":
                rows = conn.execute(f"""
                    SELECT c.id,
                           COALESCE(u.display_name, c.username) as username,
                           c.message,
                           c.created_at,
                           {room_expr} as room
                    FROM chat_messages c
                    LEFT JOIN users u ON c.username = u.username
                    WHERE c.id > ?
                    ORDER BY c.id ASC
                    LIMIT 200
                """, (since_id,)).fetchall()
            else:
                rows = conn.execute(f"""
                    SELECT c.id,
                           COALESCE(u.display_name, c.username) as username,
                           c.message,
                           c.created_at,
                           {room_expr} as room
                    FROM chat_messages c
                    LEFT JOIN users u ON c.username = u.username
                    WHERE c.id > ?
                      AND lower({room_expr}) = lower(?)
                    ORDER BY c.id ASC
                    LIMIT 200
                """, (since_id, room_id)).fetchall()

            msgs = [dict(r) for r in rows]

    except Exception as e:
        print(f"Chat Load Error: {e}")
        msgs = []
    finally:
        try:
            conn.close()
        except Exception:
            pass

    return jsonify({"ok": True, "messages": msgs})


