def get_active_chat_users():
    import time
    import random
    # Rotate every 3 minutes (180 seconds)
    seed = int(time.time() / 180) 
    random.seed(seed)
    
    # Select 10-18 users
    count = random.randint(10, 18)
    active = random.sample(MOCK_CHAT_USERS_POOL, count)
    return active

