def send_telegram_message(chat_id: str, text: str) -> bool:
    """Send message via Telegram Bot API
    
    Args:
        chat_id: Telegram chat ID (user's chat ID)
        text: Message text (supports HTML formatting)
    
    Returns:
        True if message sent successfully, False otherwise
    """
    import os
    try:
        import requests
    except ImportError:
        print("[TELEGRAM] requests module not available")
        return False
    
    token = os.getenv("TELEGRAM_BOT_TOKEN")
    if not token:
        print("[TELEGRAM] ⚠️ TELEGRAM_BOT_TOKEN not set in environment")
        return False
    
    if not chat_id:
        print("[TELEGRAM] ⚠️ No chat_id provided")
        return False
    
    try:
        url = f"https://api.telegram.org/bot{token}/sendMessage"
        payload = {
            "chat_id": chat_id,
            "text": text,
            "parse_mode": "HTML"
        }
        res = requests.post(url, json=payload, timeout=10)
        
        if res.status_code == 200:
            print(f"[TELEGRAM] ✅ Message sent to {chat_id}")
            return True
        else:
            print(f"[TELEGRAM] ❌ Failed: {res.status_code} - {res.text}")
            return False
    except Exception as e:
        print(f"[TELEGRAM] ❌ Error sending message: {e}")
        return False

def db() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH, timeout=60, check_same_thread=False, isolation_level=None)
    conn.row_factory = sqlite3.Row
    # Enable WAL mode for better concurrent access
    try:
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA busy_timeout=60000")
        conn.execute("PRAGMA synchronous=NORMAL")
        conn.execute("PRAGMA cache_size=10000")
    except:
        pass
    return conn

def db_execute_with_retry(query, params=(), max_retries=5):
    """Execute a query with retry on database lock"""
    import time
    for attempt in range(max_retries):
        try:
            conn = db()
            cursor = conn.execute(query, params)
            conn.commit()
            result = cursor.fetchall() if cursor.description else None
            conn.close()
            return result
        except sqlite3.OperationalError as e:
            if "database is locked" in str(e) and attempt < max_retries - 1:
                time.sleep(0.1 * (2 ** attempt))  # Exponential backoff
                continue
            raise
        except Exception as e:
            try:
                conn.close()
            except:
                pass
            raise


# Backward compatible alias (some older parts called db_connect)
def db_connect() -> sqlite3.Connection:
    return db()


