        ("dashboard", "/api/app/dashboard", "📊", "Real Islemi"),
        ("copy-trading", "/api/app/copy-trading", "👥", "Copy Trading"),
        ("ai-leverage", "/api/app/ai-leverage", "🤖", "AI Kaldıraç"),
        ("profile", "/api/app/profile", "👤", "Profil"),
        ("chat", "/api/app/chat", "💬", "Canlı Sohbet"),
        ("pnl", "/api/app/pnl-reporting-center", "📄", "Kar/Zarar Raporu"),
        ("education", "/api/app/education", "🎓", "Eğitim Merkezi"),
        ("market", "/api/app/market", "📈", "Piyasa Analizi"),
        ("history", "/api/app/history", "🕒", "İşlem Geçmişi"),
        ("portfolio", "/api/app/portfolio", "📊", "Portföy Analizi"),
