def get_user_header_html(username, package="Temel", usage=0, limit=300, exchange_status=None, balance=0.0):
    """Generate user header HTML with exchange status and balance - FIXED MODERN DESIGN"""
    import html as html_module
    username_escaped = html_module.escape(username) if username else 'Kullanıcı'
    first_letter = username[0].upper() if username else 'U'
    package_escaped = html_module.escape(str(package))
    
    # Handle unlimited (-1) limit
    if limit < 0:
        limit_display = "∞"
        pct = 0
    else:
        limit_display = str(limit)
        pct = int((usage / limit * 100) if limit > 0 else 0)
    
    # Exchange status defaults
    if exchange_status is None:
        exchange_status = {"OKX": False, "Binance": False, "Bybit": False, "GateIO": False}
    
    # Build exchange badges
    exchange_badges = []
    for ex, connected in exchange_status.items():
        color = "#22c55e" if connected else "#ef4444"
        exchange_badges.append(
            f'<span style="display:inline-flex;align-items:center;padding:4px 10px;background:rgba(255,255,255,0.05);border-radius:6px;font-size:11px;color:#9ca3af;margin-right:6px;">'
            f'<span style="width:6px;height:6px;border-radius:50%;background:{color};margin-right:6px;"></span>{html_module.escape(ex)}</span>'
        )
    
    exchanges_html = "".join(exchange_badges)
    balance_str = f"{float(balance):.2f}" if balance else "0.00"
    
    return f"""
    <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));gap:16px;margin-bottom:24px;">
        <!-- User Card -->
        <div style="background:linear-gradient(135deg, #1a1a1a 0%, #252525 100%);border:1px solid rgba(255,255,255,0.08);border-radius:16px;padding:20px;display:flex;align-items:center;gap:16px;">
            <div style="width:52px;height:52px;border-radius:50%;background:linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);display:flex;align-items:center;justify-content:center;color:white;font-size:20px;font-weight:bold;box-shadow:0 4px 15px rgba(59,130,246,0.3);">
                {first_letter}
            </div>
            <div>
                <div style="color:white;font-weight:600;font-size:15px;margin-bottom:2px;">{username_escaped}</div>
                <div style="color:#6b7280;font-size:12px;">{package_escaped} Paketi</div>
            </div>
        </div>
        
        <!-- Exchanges Card -->
        <div style="background:linear-gradient(135deg, #1a1a1a 0%, #252525 100%);border:1px solid rgba(255,255,255,0.08);border-radius:16px;padding:20px;">
            <div style="color:#6b7280;font-size:11px;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:12px;font-weight:500;">Borsalar</div>
            <div style="display:flex;flex-wrap:wrap;gap:4px;">
                {exchanges_html}
            </div>
        </div>
        
        <!-- Balance Card -->
        <div style="background:linear-gradient(135deg, #1a1a1a 0%, #252525 100%);border:1px solid rgba(255,255,255,0.08);border-radius:16px;padding:20px;">
            <div style="color:#6b7280;font-size:11px;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px;font-weight:500;">Toplam Bakiye</div>
            <div style="color:white;font-size:24px;font-weight:700;">${balance_str} <span style="font-size:13px;color:#6b7280;font-weight:400;">USDT</span></div>
        </div>
        
        <!-- Usage Card -->
        <div style="background:linear-gradient(135deg, #1a1a1a 0%, #252525 100%);border:1px solid rgba(255,255,255,0.08);border-radius:16px;padding:20px;">
            <div style="color:#6b7280;font-size:11px;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px;font-weight:500;">Kullanım Hakkı</div>
            <div style="color:white;font-size:24px;font-weight:700;margin-bottom:10px;">{usage}<span style="color:#6b7280;">/</span>{limit_display}</div>
            <div style="width:100%;height:4px;background:rgba(255,255,255,0.08);border-radius:2px;overflow:hidden;">
                <div style="width:{pct}%;height:100%;background:linear-gradient(90deg, #3b82f6, #22c55e);border-radius:2px;"></div>
            </div>
        </div>
    </div>
    """


