        conn = db()
        row = conn.execute("""
            SELECT package_name, package_limit FROM users WHERE username=?
        """, (username,)).fetchone()
        conn.close()
        
        if row:
            pkg_name = row[0] or "Temel"
            limit = int(row[1] or 300)
