@app.route("/api/admin/education/videos")
def api_admin_education_videos():
    """List all education videos/webinars (admin only)"""
    if not session.get("logged_in"): 
        return jsonify({"ok": False, "error": "AUTH_REQUIRED"}), 401
    try:
        conn = db()
        conn.execute("""
            CREATE TABLE IF NOT EXISTS education_videos (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                url TEXT NOT NULL,
                type TEXT DEFAULT 'video',
                duration INTEGER DEFAULT 0,
                description TEXT,
                created_at INTEGER DEFAULT (strftime('%s', 'now')),
                updated_at INTEGER DEFAULT (strftime('%s', 'now'))
            )
        """)
        conn.commit()
        
        rows = conn.execute("SELECT id, title, url, type, duration, description, created_at FROM education_videos ORDER BY created_at DESC").fetchall()
        videos = []
        for r in rows:
            videos.append({
                "id": r[0], "title": r[1], "url": r[2], "type": r[3],
                "duration": r[4], "description": r[5], "created_at": r[6]
            })
        conn.close()
        return jsonify({"ok": True, "videos": videos})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})

@app.route("/api/admin/education/video/<int:video_id>")
def api_admin_education_video_get(video_id):
    """Get single video details (admin only)"""
    if not session.get("logged_in"): 
        return jsonify({"ok": False, "error": "AUTH_REQUIRED"}), 401
    try:
        conn = db()
        row = conn.execute("SELECT id, title, url, type, duration, description FROM education_videos WHERE id=?", (video_id,)).fetchone()
        conn.close()
        if row:
            return jsonify({"ok": True, "video": {"id": row[0], "title": row[1], "url": row[2], "type": row[3], "duration": row[4], "description": row[5]}})
        return jsonify({"ok": False, "error": "NOT_FOUND"}), 404
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})

@app.post("/api/admin/education/video/save")
def api_admin_education_video_save():
    """Create or update video/webinar (admin only)"""
    if not session.get("logged_in"): 
        return jsonify({"ok": False, "error": "AUTH_REQUIRED"}), 401
    try:
        data = request.get_json()
        title = data.get("title", "").strip()
        url = data.get("url", "").strip()
        vtype = data.get("type", "video")
        duration = int(data.get("duration", 0) or 0)
        description = data.get("description", "").strip()
        video_id = data.get("id")
        
        if not title or not url:
            return jsonify({"ok": False, "error": "TITLE_AND_URL_REQUIRED"}), 400
        
        conn = db()
        conn.execute("""
            CREATE TABLE IF NOT EXISTS education_videos (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                url TEXT NOT NULL,
                type TEXT DEFAULT 'video',
                duration INTEGER DEFAULT 0,
                description TEXT,
                created_at INTEGER DEFAULT (strftime('%s', 'now')),
                updated_at INTEGER DEFAULT (strftime('%s', 'now'))
            )
        """)
        conn.commit()
        
        if video_id:
            conn.execute("""
                UPDATE education_videos 
                SET title=?, url=?, type=?, duration=?, description=?, updated_at=strftime('%s', 'now')
                WHERE id=?
            """, (title, url, vtype, duration, description, video_id))
        else:
            conn.execute("""
                INSERT INTO education_videos (title, url, type, duration, description)
                VALUES (?, ?, ?, ?, ?)
            """, (title, url, vtype, duration, description))
        conn.commit()
        conn.close()
        return jsonify({"ok": True, "message": "Kaydedildi"})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})

@app.post("/api/admin/education/video/<int:video_id>/delete")
def api_admin_education_video_delete(video_id):
    """Delete video/webinar (admin only)"""
    if not session.get("logged_in"): 
        return jsonify({"ok": False, "error": "AUTH_REQUIRED"}), 401
    try:
        conn = db()
        conn.execute("DELETE FROM education_videos WHERE id=?", (video_id,))
        conn.commit()
        conn.close()
        return jsonify({"ok": True, "message": "Silindi"})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})

@app.route('/admin/webhooks')
def admin_webhooks_page():
    if not session.get("logged_in"): return redirect("/api/app/login")
    
