@app.post("/api/mode")
def api_mode_toggle():
    """UI demo/real toggle.
    ÖNEMLİ: Mod değişince demo verilerini SİLMEYİZ. Sadece UI'da ilgili moda ait veriler gösterilir.
    """
    if not session.get("logged_in"):
        return jsonify({"ok": False, "error": "LOGIN_REQUIRED"}), 401

    j = request.get_json(silent=True) or {}
    mode = str(j.get("mode") or session.get("ui_mode") or session.get("mode") or session.get("account_mode") or "demo").lower()
    if mode in ("live", "real"):
        mode = "real"
    if mode not in ("demo", "real"):
        return jsonify({"ok": False, "error": "BAD_MODE"}), 400

    session["ui_mode"] = mode
    session["mode"] = mode
    session["account_mode"] = ("REAL" if mode == "real" else "DEMO")

    # users tablosunda da sakla (UI refresh sonrası aynı gelsin)
    try:
        uid = int(session.get("user_id") or 0)
        if uid:
            conn = db()
            try:
                conn.execute("UPDATE users SET account_mode=? WHERE rowid=? OR id=?", (session["account_mode"], uid, uid))
                conn.commit()
            finally:
                conn.close()
    except Exception:
        pass

    return jsonify({"ok": True, "mode": mode}), 200

# @app.post("/api/demo/trade")
def api_demo_trade():
    """Execute a demo trade - SPOT mantığı ile çalışır"""
    if not session.get("logged_in"): return jsonify({"ok": False}), 401
    user_id = session.get("user_id", 0)

    j = request.get_json(silent=True) or {}
    amount = float(j.get("amount", 0))
    side = str(j.get("side", "buy")).lower()
    symbol = str(j.get("symbol", "")).upper()

    # DEMO: Coin limiti kontrolü (sadece 1 coin)
    can_open, max_coins = can_open_new_coin(user_id, is_demo=True)
    if not can_open:
        return jsonify({"ok": False, "error": f"Demo modda sadece {max_coins} coin ile işlem yapabilirsiniz"}), 403

    # DEMO: Aylık işlem limiti kontrolü
    can_trade, remaining = can_execute_trade(user_id)
    if not can_trade:
        return jsonify({"ok": False, "error": "Aylık işlem limitiniz doldu"}), 403

    # Get live price
    prices = get_live_crypto_prices()
    price = prices.get(symbol) or prices.get(symbol.replace("/", "")) or 0

    if amount <= 0:
        return jsonify({"ok": False, "error": "Geçersiz miktar"}), 400

    # SPOT mantığı: Sadece alım (buy) işlemi
    if side != "buy":
        return jsonify({"ok": False, "error": "Demo modda sadece alım (buy) işlemi yapılabilir"}), 400

    # Deduct from balance
    new_balance = update_demo_balance(user_id, -amount)

    return jsonify({
        "ok": True, 
        "new_balance": new_balance,
        "trade": {"symbol": symbol, "amount": amount, "side": side, "price": price},
        "remaining_trades": remaining - 1
    })

def api_demo_profit():
    """Add profit/loss to demo balance"""
    if not session.get("logged_in"): return jsonify({"ok": False}), 401
    user_id = session.get("user_id", 0)
    
    j = request.get_json(silent=True) or {}
    profit = float(j.get("profit", 0))  # Can be negative for loss
    
    new_balance = update_demo_balance(user_id, profit)
    return jsonify({"ok": True, "new_balance": new_balance, "profit": profit})


