# --- Telegram Helpers ---
def send_telegram_message(text):
    try:
        token = os.getenv("TELEGRAM_BOT_TOKEN", "")
        chat_id = os.getenv("TELEGRAM_ADMIN_CHAT_ID", "")
        if not token or not chat_id:
            return
        url = f"https://api.telegram.org/bot{token}/sendMessage"
        requests.post(url, json={"chat_id": chat_id, "text": text}, timeout=10)
    except Exception as e:
        print("Telegram error:", e)

@app.post("/api/payment/request")
def api_payment_request():
    if not session.get("logged_in"):
        return jsonify({"ok": False, "error": "Login required"}), 401
    
    data = request.get_json() or {}
    pkg = data.get("package", "bilinmiyor")
    amount = data.get("amount", "")
    payment_method = data.get("payment_method", "belirtilmedi")
    
    username = session.get("username", "kullanıcı")
    user_id = session.get("user_id", 0)
    
    from datetime import datetime
    now = datetime.now().strftime("%d.%m.%Y %H:%M")
    
    # Telegram mesajı - soru işareti yok
    msg = f"""💳 ÖDEME TALEBİ

Kullanıcı: {username} (ID: {user_id})
Paket: {pkg}
Tutar: {amount}
Ödeme Yöntemi: {payment_method}
Tarih: {now}

Lütfen ödemeyi kontrol edin."""
    
    send_telegram_message(msg)
    return jsonify({"ok": True, "message": "Ödeme talebi gönderildi"})

