# -----------------------------
# Inline Jinja templates loader
# -----------------------------
def _setup_inline_templates():
    try:
        from jinja2 import DictLoader
        templates = {}
        # base ve tüm sayfalar (varsa) loader içine alınır
        for k, v in globals().items():
            if not isinstance(k, str):
                continue
        # bilinen şablonlar
        for name in [
            "base",
        ]:
            pass

        templates_map = {}
        # Base template adı tüm extend'lerde "base"
        if "BASE_TEMPLATE" in globals():
            templates_map["base"] = globals()["BASE_TEMPLATE"]

        # Sayfa template stringleri
        for var in [
            "LOGIN_TEMPLATE",
            "DASHBOARD_TEMPLATE",
            "ADMIN_TEMPLATE",
            "ARBITRAGE_MONITOR_TEMPLATE",
            "GETTING_STARTED_GUIDE_TEMPLATE",
        ]:
            if var in globals() and isinstance(globals()[var], str):
                # render_template ile kullanılacak isimler (isteğe bağlı)
                templates_map[var] = globals()[var]

        # Bazı sayfalar render_template_string ile direkt string kullanıyor,
        # ama extends/include çalışması için base yeterli.
        if templates_map:
            app.jinja_loader = DictLoader(templates_map)
    except Exception:
        # loader kurulamazsa sayfalar yine render_template_string ile çalışır
        return

_setup_inline_templates()

