@app.route("/api/app/referral")
def api_app_referral():
    try:
        if not session.get("logged_in"):
            return redirect("/api/app/login")

        username = session.get("username", "")
        user = get_user(username)
        if not user:
            return redirect("/api/app/login")

        referral_count = 0
        referral_earnings = 0
        referrals = []

        try:
            with db() as conn:
                cursor = conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='referrals'")
                if cursor.fetchone():
                    result = conn.execute("SELECT COUNT(*) FROM referrals WHERE referrer_id = (SELECT rowid FROM users WHERE username = ?)", (username,)).fetchone()
                    referral_count = result[0] if result else 0
                    result = conn.execute("SELECT referral_earnings FROM users WHERE username = ?", (username,)).fetchone()
                    referral_earnings = result[0] if result and result[0] else 0
        except Exception as e:
            print(f"[REFERRAL DB ERROR] {e}")

        # Template değişkenleri ile eşleştir
        return render_template_string(REFERRAL_TEMPLATE,
                                     sidebar=get_sidebar_html("referral"),
                                     referral_code=username,
                                     share_link=f"http://5.75.188.42/api/app/register?ref={username}",
                                     total_referrals=referral_count,
                                     active_referrals=referral_count,  # Şimdilik aynı
                                     total_earnings=referral_earnings,
                                     total_trades=0,
                                     success_rate=0.0,
                                     total_pnl=0.0,
                                     avg_volume=0.0,
                                     referrals=referrals)
    except Exception as e:
        print(f"[REFERRAL ERROR] {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"error": "internal server error", "details": str(e)}), 500



# === END REFERRAL SYSTEM ===

# === DEMO/REAL MODE POSITIONS API ===
@app.route("/api/positions/list")
def api_positions_list():
    """Get positions filtered by current mode (DEMO/REAL)"""
    if not session.get("logged_in"):
        return jsonify({"ok": False, "error": "Login required"}), 401
    
    username = session.get("username")
    mode = session.get("ui_mode", "demo").lower()
    
    with db() as conn:
        conn.row_factory = sqlite3.Row
        
        if mode == "real":
            # Real positions
            rows = conn.execute("""
                SELECT id, coin, side, amount_usdt, entry_price, current_price, pnl, status, created_at
                FROM real_positions
                WHERE user_id = (SELECT rowid FROM users WHERE username = ?)
                AND status IN ('open', 'waiting')
                ORDER BY created_at DESC
            """, (username,)).fetchall()
        else:
            # Demo positions
            rows = conn.execute("""
                SELECT id, coin, side, amount_usdt, entry_price, current_price, pnl, status, created_at
                FROM demo_positions
                WHERE user_id = (SELECT rowid FROM users WHERE username = ?)
                AND status IN ('open', 'waiting')
                ORDER BY created_at DESC
            """, (username,)).fetchall()
        
        positions = [dict(row) for row in rows]
    
    return jsonify({"ok": True, "mode": mode, "positions": positions})

# === END DEMO/REAL MODE POSITIONS API ===

# === SELL AI API ENDPOINT ===
@app.route("/api/sell/decision")
def api_sell_decision():
    """Get SELL AI decision for a position"""
    if not session.get("logged_in"):
        return jsonify({"ok": False, "error": "Login required"}), 401
    
    symbol = request.args.get("symbol", "")
    entry_price = float(request.args.get("entry_price", 0))
    current_price = float(request.args.get("current_price", 0))
    entry_time = int(request.args.get("entry_time", 0))
    qty = float(request.args.get("qty", 0))
    
    if not symbol or entry_price <= 0:
        return jsonify({"ok": False, "error": "Invalid parameters"}), 400
    
    # Get current price if not provided
    if current_price <= 0:
        current_price = _au_demo_price(symbol)
    
    decision = sell_ai_decision_engine(
        symbol=symbol,
        entry_price=entry_price,
        qty=qty,
        entry_time=entry_time,
        current_price=current_price,
        mode=session.get("ui_mode", "demo")
    )
    
    return jsonify({"ok": True, **decision})

# === END SELL AI API ENDPOINT ===

