@app.route('/profile')
@app.route('/api/app/profile')
def page_profile():
    if not session.get("logged_in"): return redirect("/api/app/login")
    
    # Get user data from database
    user_id = session.get("user_id")
    username = session.get("username", "")
    
    try:
        conn = db()
        # Check available columns
        cols_info = conn.execute("PRAGMA table_info(users)").fetchall()
        col_names = [c[1] for c in cols_info]
        
        # Build select query dynamically
        select_fields = ["email", "package_name", "expires_at", "telegram_chat_id", "two_fa_enabled"]
        if "api_okx_key" in col_names:
            select_fields.append("api_okx_key")
        
        row = conn.execute(f"SELECT {', '.join(select_fields)} FROM users WHERE id=?", (user_id,)).fetchone()
        conn.close()
        if row:
            user_data = {
                "username": username,
                "email": row[0] or "",
                "package": row[1] or "trial",
                "expires_at": row[2] or "Süresiz",
                "telegram_chat_id": row[3] or "",
                "two_fa_enabled": bool(row[4]) if row[4] else False,
                "api_okx_key": row[5] if len(row) > 5 else ""
            }
        else:
            user_data = {"username": username, "email": "", "package": "trial", "expires_at": "Süresiz", "telegram_chat_id": "", "two_fa_enabled": False, "api_okx_key": ""}
    except Exception as e:
        print(f"[PROFILE] Error loading user data: {e}")
        user_data = {"username": username, "email": "", "package": "trial", "expires_at": "Süresiz", "telegram_chat_id": "", "two_fa_enabled": False, "api_okx_key": ""}
    
    return render_template_string(PROFILE_TEMPLATE, sidebar=get_sidebar_html("profile"), user=user_data)

@app.get('/api/user/profile')
def api_user_profile():
    if not session.get("logged_in"):
        return jsonify({"ok": False, "error": "Login required"}), 401
    
    user_id = session.get("user_id")
    username = session.get("username", "")
    
    try:
        conn = db()
        
        # First check what columns exist
        cols_info = conn.execute("PRAGMA table_info(users)").fetchall()
        col_names = [c[1] for c in cols_info]
        
        # Build query based on available columns
        select_cols = ["username"]
        if "email" in col_names:
            select_cols.append("email")
        if "package_name" in col_names:
            select_cols.append("package_name")
        if "expires_at" in col_names:
            select_cols.append("expires_at")
        if "telegram_chat_id" in col_names:
            select_cols.append("telegram_chat_id")
        if "two_fa_enabled" in col_names:
            select_cols.append("two_fa_enabled")
        
        query = f"SELECT {', '.join(select_cols)} FROM users WHERE id=?"
        row = conn.execute(query, (user_id,)).fetchone()
        
        # Fallback to username search
        if not row and username:
            row = conn.execute(f"SELECT {', '.join(select_cols)} FROM users WHERE username=?", (username,)).fetchone()
        
        conn.close()
        
        if row:
            result = {"username": row[0] or username}
            idx = 1
            if "email" in select_cols[1:]:
                result["email"] = row[idx] or ""
                idx += 1
            if "package_name" in select_cols[1:]:
                result["package"] = row[idx] or "trial"
                idx += 1
            if "expires_at" in select_cols[1:]:
                result["expires_at"] = row[idx] or "Süresiz"
                idx += 1
            if "telegram_chat_id" in select_cols[1:]:
                result["telegram_chat_id"] = row[idx] or ""
                idx += 1
            if "two_fa_enabled" in select_cols[1:]:
                result["two_fa_enabled"] = bool(row[idx])
            else:
                result["two_fa_enabled"] = False
            
            return jsonify({"ok": True, "user": result})
        
        # Return basic info from session if DB lookup fails
        return jsonify({"ok": True, "user": {
            "username": username,
            "email": "",
            "package": "trial",
            "expires_at": "Süresiz",
            "telegram_chat_id": "",
            "two_fa_enabled": False
        }})
    except Exception as e:
        print(f"[PROFILE API] Error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"ok": True, "user": {
            "username": username,
            "email": "",
            "package": "trial",
            "expires_at": "Süresiz",
            "telegram_chat_id": "",
            "two_fa_enabled": False
        }})

@app.post('/api/user/update-telegram')
def api_user_update_telegram():
    """Update user's Telegram Chat ID and send test message"""
    if not session.get("logged_in"):
        return jsonify({"ok": False, "error": "Login required"}), 401
    
    user_id = session.get("user_id")
    data = request.get_json() or {}
    chat_id = str(data.get("telegram_chat_id", "")).strip()
    
    try:
        conn = db()
        
        # Check if column exists
        cols = conn.execute("PRAGMA table_info(users)").fetchall()
        col_names = [c[1] for c in cols]
        
        if "telegram_chat_id" not in col_names:
            # Add column if missing
            conn.execute("ALTER TABLE users ADD COLUMN telegram_chat_id TEXT")
            conn.commit()
        
        # Update chat ID
        conn.execute("UPDATE users SET telegram_chat_id=? WHERE id=?", (chat_id, user_id))
        conn.commit()
        conn.close()
        
        # Send test message if chat_id is provided
        if chat_id:
            success = send_telegram_message(
                chat_id,
                "🎉 <b>Telegram Bildirimleri Aktif!</b>\n\n"
                "Artık BUY/SELL işlem alertleri bu chate gelecek.\n\n"
                "✅ Test mesajı başarıyla gönderildi!"
            )
            
            if success:
                return jsonify({
                    "ok": True,
                    "message": "Telegram kaydedildi ve test mesajı gönderildi! ✅"
                })
            else:
                return jsonify({
                    "ok": True,
                    "warning": "Chat ID kaydedildi ama mesaj gönderilemedi. TELEGRAM_BOT_TOKEN kontrol edin."
                })
        
        return jsonify({"ok": True, "message": "Telegram ayarları temizlendi"})
        
    except Exception as e:
        print(f"[TELEGRAM UPDATE] Error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"ok": False, "error": str(e)}), 500


@app.post('/api/user/change-password')
def api_user_change_password():
    if not session.get("logged_in"):
        return jsonify({"ok": False, "error": "Login required"}), 401
    
    data = request.get_json() or {}
    current = data.get("current_password")
    new_pass = data.get("new_password")
    
    if not current or not new_pass:
        return jsonify({"ok": False, "error": "Tüm alanları doldurun"})
    
    if len(new_pass) < 6:
        return jsonify({"ok": False, "error": "Şifre en az 6 karakter olmalı"})
    
    user_id = session.get("user_id")
    try:
        conn = db()
        row = conn.execute("SELECT password FROM users WHERE id=?", (user_id,)).fetchone()
        
        if not row:
            conn.close()
            return jsonify({"ok": False, "error": "Kullanıcı bulunamadı"})
        
        # Check current password (simple comparison, should use hash in production)
        stored_pass = row[0]
        if stored_pass != current:
            conn.close()
            return jsonify({"ok": False, "error": "Mevcut şifre hatalı"})
        
        # Update password
        conn.execute("UPDATE users SET password=?, updated_at=? WHERE id=?", (new_pass, int(time.time()), user_id))
        conn.commit()
        conn.close()
        return jsonify({"ok": True, "message": "Şifre güncellendi"})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)})

