        conn.execute("""
            CREATE TABLE IF NOT EXISTS settings (
                key TEXT PRIMARY KEY,
                value TEXT
            )
        """)
        conn.commit()
        
        rows = conn.execute("SELECT key, value FROM settings").fetchall()
        conn.close()
        
        settings = {r[0]: r[1] for r in rows}
