# === CRITICAL: START DEMO & REAL TRADING ENGINES ===
def _start_trading_engines():
    """Start both demo and real trading worker threads"""
    import threading
    
    # === NEW: Demo Auto Trade Processor ===
    def demo_auto_trade_processor():
        """
        Reads auto_positions table for waiting demo trades.
        Executes fake BUY, waits 2-5 minutes, then fake SELL with profit.
        Logs all transactions to transaction_history.
        
        Settings:
        - Target: ~15 trades per day (~96 min cycle)
        - Gross Profit: 0.50%
        - Trading Fee: 0.20% (total for BUY+SELL)
        - Net Profit: 0.30%
        """
        import random
        import ccxt
        
        # Trading parameters
        GROSS_PROFIT_PCT = 0.50  # 0.50% gross profit
        FEE_PCT = 0.20           # 0.20% fee (BUY + SELL combined)
        NET_PROFIT_PCT = GROSS_PROFIT_PCT - FEE_PCT  # 0.30% net
        
        # Timing parameters (for ~15 trades/day)
        CHECK_INTERVAL = 300         # 5 minutes between checks
        BUY_TO_SELL_WAIT = (120, 300)  # 2-5 minutes between BUY and SELL
        CYCLE_WAIT = (4800, 6000)      # 80-100 minutes wait after SELL cycle
        
        print("[DEMO_AUTO] 🎯 Demo auto trade processor starting...")
        print(f"[DEMO_AUTO] 📊 Settings: {NET_PROFIT_PCT}% net profit, ~15 trades/day")
        
        while True:
            try:
                time.sleep(CHECK_INTERVAL)  # Check every 5 minutes
                
                conn = db()
                # Get all WAITING demo trades
                waiting = conn.execute("""
                    SELECT id, user_id, coin, amount_usdt, target_pct, created_at 
                    FROM auto_positions 
                    WHERE status='waiting' AND mode='demo'
                    LIMIT 5
                """).fetchall()
                
                if not waiting:
                    conn.close()
                    continue
                
                for row in waiting:
                    trade_id, user_id, coin, amount_usdt, target_pct, created_at = row
                    
                    # Normalize coin format
                    symbol = coin if "/" in coin else f"{coin}/USDT"
                    
                    # Get current price
                    try:
                        ex = ccxt.okx({"enableRateLimit": True, "timeout": 5000})
                        ticker = ex.fetch_ticker(symbol)
                        entry_price = float(ticker.get("last", 0))
                    except:
                        entry_price = 0
                    
                    if entry_price <= 0:
                        continue
                    
                    # Calculate quantity and profit target
                    qty = amount_usdt / entry_price
                    # Use configured profit settings
                    gross_pct = GROSS_PROFIT_PCT  # 0.50%
                    fee_pct = FEE_PCT              # 0.20%
                    net_pct = NET_PROFIT_PCT       # 0.30% net
                    
                    exit_price = entry_price * (1 + gross_pct / 100)
                    gross_profit = amount_usdt * (gross_pct / 100)
                    fee = amount_usdt * (fee_pct / 100)
                    profit = gross_profit - fee  # Net profit after fee
                    
                    # Get username for logging
                    user_row = conn.execute("SELECT username FROM users WHERE id=?", (user_id,)).fetchone()
                    username = user_row[0] if user_row else f"user_{user_id}"
                    
                    # === FAKE BUY ===
                    conn.execute("""
                        UPDATE auto_positions 
                        SET status='open', entry_price=?, entry_at=datetime('now')
                        WHERE id=?
                    """, (entry_price, trade_id))
                    conn.commit()
                    
                    # DEDUCT from demo balance on BUY
                    try:
                        new_balance = update_demo_balance(int(user_id), -abs(amount_usdt))
                        print(f"[DEMO_AUTO] 💰 Balance deducted: -{amount_usdt} USDT → {new_balance:.2f}")
                    except Exception as bal_err:
                        print(f"[DEMO_AUTO] ⚠️ Balance deduct error: {bal_err}")
                    
                    # Log BUY to transaction_history
                    try:
                        conn.execute("""
                            INSERT INTO transaction_history (
                                username, type, symbol, amount, price, total,
                                profit, timestamp, is_simulated, mode
                            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """, (username, "BUY", symbol, qty, entry_price, amount_usdt, 0.0, int(time.time()), 1, "demo"))
                        conn.commit()
                        print(f"[HISTORY] ✅ BUY recorded: {username} {symbol} {amount_usdt} USDT @ {entry_price:.4f}", flush=True)
                    except Exception as hist_err:
                        print(f"[HISTORY] ❌ BUY record failed: {hist_err}", flush=True)
                    
                    print(f"[DEMO_AUTO] ✅ BUY {username}: {symbol} @ {entry_price:.4f} | Amount: {amount_usdt} USDT")

                    
                conn.close()
                
                # Wait 2-5 minutes before SELL (realistic trading time)
                wait_time = random.randint(BUY_TO_SELL_WAIT[0], BUY_TO_SELL_WAIT[1])
                print(f"[DEMO_AUTO] ⏳ Waiting {wait_time//60}m {wait_time%60}s before SELL...")
                time.sleep(wait_time)
                
                conn = db()
                # Get OPEN demo trades older than 10 seconds
                open_trades = conn.execute("""
                    SELECT id, user_id, coin, amount_usdt, entry_price, target_pct
                    FROM auto_positions 
                    WHERE status='open' AND mode='demo'
                    LIMIT 5
                """).fetchall()
                
                for row in open_trades:
                    trade_id, user_id, coin, amount_usdt, entry_price, target_pct = row
                    
                    symbol = coin if "/" in coin else f"{coin}/USDT"
                    
                    # Get current price for exit
                    try:
                        ex = ccxt.okx({"enableRateLimit": True, "timeout": 5000})
                        ticker = ex.fetch_ticker(symbol)
                        current_price = float(ticker.get("last", 0))
                    except:
                        current_price = entry_price * 1.005  # Fake 0.5% profit
                    
                    # Calculate PNL with fee deduction
                    gross_pct = GROSS_PROFIT_PCT  # 0.50%
                    fee_pct = FEE_PCT              # 0.20%
                    
                    exit_price = entry_price * (1 + gross_pct / 100)
                    gross_profit = amount_usdt * (gross_pct / 100)
                    fee = amount_usdt * (fee_pct / 100)
                    profit = gross_profit - fee  # Net profit: ~0.30%
                    qty = amount_usdt / entry_price if entry_price > 0 else 0
                    
                    # Get username
                    user_row = conn.execute("SELECT username FROM users WHERE id=?", (user_id,)).fetchone()
                    username = user_row[0] if user_row else f"user_{user_id}"
                    
                    # === FAKE SELL ===
                    # Loop: Set status back to 'waiting' so it will BUY again!
                    conn.execute("""
                        UPDATE auto_positions 
                        SET status='waiting', current_price=?, pnl=COALESCE(pnl,0)+?, entry_price=NULL, exit_at=datetime('now')
                        WHERE id=?
                    """, (exit_price, profit, trade_id))
                    conn.commit()
                    
                    # Update user demo balance with profit
                    try:
                        new_balance = update_demo_balance(int(user_id), amount_usdt + profit)
                    except:
                        new_balance = 0
                    
                    # Log SELL to transaction_history
                    try:
                        conn.execute("""
                            INSERT INTO transaction_history (
                                username, type, symbol, amount, price, total,
                                profit, timestamp, is_simulated, mode
                            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """, (username, "SELL", symbol, qty, exit_price, amount_usdt + profit, profit, int(time.time()), 1, "demo"))
                        conn.commit()
                        print(f"[HISTORY] ✅ SELL recorded: {username} {symbol} {amount_usdt} USDT @ {exit_price:.4f} | Profit: {profit:.2f}", flush=True)
                    except Exception as hist_err:
                        print(f"[HISTORY] ❌ SELL record failed: {hist_err}", flush=True)
                    
                    print(f"[DEMO_AUTO] 💰 SELL {username}: {symbol} @ {exit_price:.4f} | Profit: +{profit:.2f} USDT | Balance → {new_balance:.2f}")

                
                conn.close()
                
                # Wait 80-100 minutes before next trade cycle (~15 trades/day)
                cycle_wait = random.randint(CYCLE_WAIT[0], CYCLE_WAIT[1])
                print(f"[DEMO_AUTO] 🔄 Cycle complete. Next trade in {cycle_wait//60}m...")
                time.sleep(cycle_wait)
                
            except Exception as e:
                print(f"[DEMO_AUTO] ❌ Error: {e}")
                time.sleep(5)
    
    # Start DEMO worker thread (existing - handles manual positions)
    def start_demo_worker():
        if globals().get("_DEMO_WORKER_STARTED"):
            return
        globals()["_DEMO_WORKER_STARTED"] = True
        
        print("[DEMO_ENGINE] 🎮 Starting DEMO trading worker thread...")
        t = threading.Thread(target=_demo_worker_loop, name="demo_worker", daemon=True)
        t.start()
        print("[DEMO_ENGINE] ✅ DEMO worker thread started - fake trading ACTIVE!")
    
    # Start DEMO AUTO processor (NEW - handles auto_positions table)
    def start_demo_auto_processor():
        if globals().get("_DEMO_AUTO_STARTED"):
            return
        globals()["_DEMO_AUTO_STARTED"] = True
        
        print("[DEMO_AUTO] 🎯 Starting DEMO auto trade processor...")
        t = threading.Thread(target=demo_auto_trade_processor, name="demo_auto_processor", daemon=True)
        t.start()
        print("[DEMO_AUTO] ✅ DEMO auto trade processor started!")
    
    # Start REAL worker thread
    def start_real_worker():
        if globals().get("_REAL_WORKER_STARTED"):
            return
        globals()["_REAL_WORKER_STARTED"] = True
        
        print("[REAL_ENGINE] 💰 Starting REAL trading worker thread...")
        t = threading.Thread(target=_real_worker_loop, name="real_worker", daemon=True)
        t.start()
        print("[REAL_ENGINE] ✅ REAL worker thread started - OKX integration ACTIVE!")
    
    try:
        start_demo_worker()
    except Exception as e:
        print(f"[DEMO_ENGINE] ❌ Failed to start demo worker: {e}")
    
    try:
        start_demo_auto_processor()
    except Exception as e:
        print(f"[DEMO_AUTO] ❌ Failed to start demo auto processor: {e}")
    
    try:
        start_real_worker()
    except Exception as e:
        print(f"[REAL_ENGINE] ❌ Failed to start real worker: {e}")
# === END TRADING ENGINES ===


# === AU_FORCE_FLASK_RUN_V1 ===
def _au_force_run_flask():
    """
    Safety net: If server.py reaches EOF without starting a web server,
    start Flask so systemd doesn't exit successfully and kill the service.
    """
    import os
    host = os.getenv("HOST", "0.0.0.0").strip() or "0.0.0.0"
    port_s = (os.getenv("PORT", "8080") or "8080").strip()
    try:
        port = int(port_s)
    except Exception:
        port = 8080

    try:
        print(f"[BOOT] Starting Flask on {host}:{port} debug=False", flush=True)
    except Exception:
        pass

    # ✅ CRITICAL: Start trading engines BEFORE app.run() blocks
    try:
        _start_trading_engines()
        print("\n" + "="*60)
        print("🚀 TRADING ENGINES BAŞLATILDI!")
        print("   ✅ e: Fake trading ACTIVE")
        print("   ✅ Real Mode: OKX integration ACTIVE")
        print("="*60 + "\n", flush=True)
    except Exception as e:
        print(f"[STARTUP] ⚠️ Trading engine başlatma hatası: {e}", flush=True)

    # This blocks the main thread (desired under systemd)
    app.run(host=host, port=port, debug=False)



# ==================== PAKET SİSTEMİ ====================

PACKAGE_LIMITS = {
    "demo": {"max_coins": 1, "max_trades_per_month": 999999, "name": "Demo"},
    "basic": {"max_coins": 2, "max_trades_per_month": 100, "name": "Temel"},
    "premium": {"max_coins": 3, "max_trades_per_month": 600, "name": "Premium"},
    "elite": {"max_coins": 5, "max_trades_per_month": 999999, "name": "Elit"}
}

def get_user_package_limits(user_id):
    """Kullanıcının paket limitlerini getir"""
    conn = db()
    try:
        row = conn.execute("SELECT package_type, package_start, package_end FROM users WHERE id=?", (user_id,)).fetchone()
        if not row:
            return PACKAGE_LIMITS["demo"]
        pkg_type = row[0] or "demo"
        pkg_end = row[2] or 0
        if pkg_end < int(time.time()):
            return PACKAGE_LIMITS["demo"]
        return PACKAGE_LIMITS.get(pkg_type, PACKAGE_LIMITS["demo"])
    except Exception as e:
        print(f"[PACKAGE ERROR] {e}")
        return PACKAGE_LIMITS["demo"]
    finally:
        conn.close()

def get_user_active_coins(user_id):
    """Kullanıcının aktif işlem yaptığı coin sayısını getir"""
    conn = db()
    try:
        demo_coins = conn.execute("SELECT COUNT(DISTINCT symbol) FROM demo_positions WHERE user_id=? AND status='OPEN'", (user_id,)).fetchone()[0] or 0
        real_coins = conn.execute("SELECT COUNT(DISTINCT coin) FROM positions WHERE user_id=? AND status='OPEN'", (user_id,)).fetchone()[0] or 0
        return max(demo_coins, real_coins)
    except Exception as e:
        print(f"[COINS ERROR] {e}")
        return 0
    finally:
        conn.close()

def get_user_monthly_trade_count(user_id):
    """Kullanıcının bu ay yaptığı işlem sayısını getir"""
    conn = db()
    try:
        now = int(time.time())
        month_start = now - (30 * 24 * 60 * 60)
        count = conn.execute("SELECT COUNT(*) FROM transaction_history WHERE user_id=? AND timestamp > ?", (user_id, month_start)).fetchone()[0] or 0
        return count
    except Exception as e:
        print(f"[TRADE COUNT ERROR] {e}")
        return 0
    finally:
        conn.close()

def can_open_new_coin(user_id, is_demo=False):
    """Yeni coin açabilir mi?"""
    limits = get_user_package_limits(user_id)
    active_coins = get_user_active_coins(user_id)
    if is_demo:
        return active_coins < 1, limits["max_coins"]
    return active_coins < limits["max_coins"], limits["max_coins"]

def can_execute_trade(user_id):
    """İşlem yapabilir mi?"""
    limits = get_user_package_limits(user_id)
    trade_count = get_user_monthly_trade_count(user_id)
    return trade_count < limits["max_trades_per_month"], limits["max_trades_per_month"] - trade_count

if __name__ == "__main__":
    # If earlier code already started a server, it would be blocking and never reach here.
    # If we reached here, force start Flask.
    _au_force_run_flask()
