import json
import time
from datetime import datetime

def get_market_analysis(symbol, exchange_name='okx'):
    """Detaylı piyasa analizi - Mumlar, Teknik İndikatörler, Order Book"""
    import ccxt
    try:
        # Exchange seç
        exchange = getattr(ccxt, exchange_name.lower())()
        
        # Symbol format düzelt
        if '/' not in symbol:
            symbol = f"{symbol}/USDT"
        
        # 1. MUM VERİSİ (Son 100 mum - 5 dakikalık)
        ohlcv = exchange.fetch_ohlcv(symbol, timeframe='5m', limit=100)
        
        # OHLCV parse et
        closes = [candle[4] for candle in ohlcv[-50:]]  # Son 50 closing price
        highs = [candle[2] for candle in ohlcv[-50:]]
        lows = [candle[3] for candle in ohlcv[-50:]]
        volumes = [candle[5] for candle in ohlcv[-50:]]
        
        current_price = closes[-1]
        prev_price = closes[-2]
        price_change_pct = ((current_price - prev_price) / prev_price) * 100
        
        # 2. RSI HESAPLA (14 period)
        def calculate_rsi(prices, period=14):
            deltas = [prices[i] - prices[i-1] for i in range(1, len(prices))]
            gains = [d if d > 0 else 0 for d in deltas]
            losses = [-d if d < 0 else 0 for d in deltas]
            
            avg_gain = sum(gains[-period:]) / period
            avg_loss = sum(losses[-period:]) / period
            
            if avg_loss == 0:
                return 100
            rs = avg_gain / avg_loss
            rsi = 100 - (100 / (1 + rs))
            return rsi
        
        rsi = calculate_rsi(closes)
        
        # 3. EMA HESAPLA (12 ve 26 period)
        def calculate_ema(prices, period):
            multiplier = 2 / (period + 1)
            ema = [prices[0]]
            for price in prices[1:]:
                ema.append((price * multiplier) + (ema[-1] * (1 - multiplier)))
            return ema[-1]
        
        ema_12 = calculate_ema(closes, 12)
        ema_26 = calculate_ema(closes, 26)
        macd = ema_12 - ema_26
        
        # 4. BOLLINGER BANDS
        sma_20 = sum(closes[-20:]) / 20
        std_dev = (sum([(x - sma_20) ** 2 for x in closes[-20:]]) / 20) ** 0.5
        bb_upper = sma_20 + (2 * std_dev)
        bb_lower = sma_20 - (2 * std_dev)
        
        # 5. ORDER BOOK ANALİZİ
        order_book = exchange.fetch_order_book(symbol, limit=20)
        
        # Bid (alış) ve Ask (satış) pressure
        total_bid_volume = sum([bid[1] for bid in order_book['bids'][:10]])
        total_ask_volume = sum([ask[1] for ask in order_book['asks'][:10]])
        
        buy_pressure = (total_bid_volume / (total_bid_volume + total_ask_volume)) * 100
        sell_pressure = 100 - buy_pressure
        
        # 6. SON İŞLEMLER (Momentum)
        recent_trades = exchange.fetch_trades(symbol, limit=100)
        buy_trades = [t for t in recent_trades if t['side'] == 'buy']
        sell_trades = [t for t in recent_trades if t['side'] == 'sell']
        
        buy_volume = sum([t['amount'] for t in buy_trades])
        sell_volume = sum([t['amount'] for t in sell_trades])
        
        # 7. TREND BELİRLEME
        trend = "YÜKSELİŞ" if ema_12 > ema_26 else "DÜŞÜŞ"
        momentum = "GÜÇLÜ" if abs(macd) > 10 else "ZAYIF"
        
        # 8. SUPPORT/RESISTANCE
        support = min(lows[-20:])
        resistance = max(highs[-20:])
        
        # 9. VOLUME ANALİZİ
        avg_volume = sum(volumes[-20:]) / 20
        current_volume = volumes[-1]
        volume_spike = (current_volume / avg_volume) if avg_volume > 0 else 1
        
        return {
            'symbol': symbol,
            'current_price': current_price,
            'price_change_pct': price_change_pct,
            
            # Teknik İndikatörler
            'rsi': rsi,
            'rsi_signal': 'AŞIRI SATIM' if rsi < 30 else 'AŞIRI ALIM' if rsi > 70 else 'NORMAL',
            'macd': macd,
            'macd_signal': 'YUKARI' if macd > 0 else 'AŞAĞI',
            'trend': trend,
            'momentum': momentum,
            
            # Bollinger Bands
            'bb_upper': bb_upper,
            'bb_lower': bb_lower,
            'bb_position': 'ÜST BANT' if current_price > bb_upper else 'ALT BANT' if current_price < bb_lower else 'ORTA',
            
            # Order Book
            'buy_pressure': buy_pressure,
            'sell_pressure': sell_pressure,
            'order_book_signal': 'ALIŞ BASKI' if buy_pressure > 60 else 'SATIŞ BASKI' if sell_pressure > 60 else 'DENGELİ',
            
            # Volume
            'volume_spike': volume_spike,
            'volume_signal': 'YÜKSEK VOLUME' if volume_spike > 1.5 else 'NORMAL VOLUME',
            
            # Support/Resistance
            'support': support,
            'resistance': resistance,
            'distance_to_resistance': ((resistance - current_price) / current_price) * 100,
            
            # Recent Trades
            'buy_sell_ratio': (buy_volume / sell_volume) if sell_volume > 0 else 1,
            'market_sentiment': 'ALICI' if buy_volume > sell_volume else 'SATICI'
        }
    
    except Exception as e:
        print(f"[MARKET ANALYSIS ERROR] {e}")
        return None

def get_best_price(symbol):
    """Birden fazla borsadan fiyat çek ve en iyi fiyatı döndür"""
    import ccxt
    prices = {}
    
    exchanges_to_check = {
        'binance': ccxt.binance(),
        'okx': ccxt.okx(),
        'bybit': ccxt.bybit(),
        'gateio': ccxt.gateio()
    }
    
    # Symbol format düzelt (BTC/USDT formatına çevir)
    if '/' not in symbol:
        symbol = f"{symbol}/USDT"
    
    for ex_name, exchange in exchanges_to_check.items():
        try:
            ticker = exchange.fetch_ticker(symbol)
            prices[ex_name] = {
                'bid': ticker['bid'],  # Al fiyatı (satıcıların fiyatı)
                'ask': ticker['ask'],  # Sat fiyatı (alıcıların fiyatı)
                'last': ticker['last']
            }
        except Exception as e:
            print(f"[PRICE] {ex_name} error for {symbol}: {e}")
            continue
    
    if not prices:
        return None
    
    # En düşük ASK (almak için en iyi) ve en yüksek BID (satmak için en iyi)
    best_buy_exchange = min(prices.items(), key=lambda x: x[1]['ask'])
    best_sell_exchange = max(prices.items(), key=lambda x: x[1]['bid'])
    
    return {
        'symbol': symbol,
        'best_buy': {
            'exchange': best_buy_exchange[0],
            'price': best_buy_exchange[1]['ask']
        },
        'best_sell': {
            'exchange': best_sell_exchange[0],
            'price': best_sell_exchange[1]['bid']
        },
        'all_prices': prices
    }

def ai_should_sell(coin, entry_price, current_price, market_data=None):
    """Google Gemini AI ile DETAYLI teknik analiz ve sell kararı"""
    try:
        profit_pct = ((current_price - entry_price) / entry_price) * 100
        
        # Detaylı piyasa analizi al
        market = get_market_analysis(coin)
        
        if not market:
            # Fallback: Basit kar kontrolü
            if profit_pct >= 2.0:
                return {'decision': 'SELL', 'reasoning': 'Fallback: 2%+ kar', 'profit_pct': profit_pct}
            return {'decision': 'HOLD', 'reasoning': 'Fallback: Düşük kar', 'profit_pct': profit_pct}
        
        # AI'ya PROFESYONEL prompt
        prompt = f"""Sen profesyonel bir kripto trader'sın. 15 yıllık tecrüben var. Aşağıdaki TEKNİK ANALİZ verilerine göre bu pozisyonu SELL mi HOLD mu etmeliyim?

═══════════════════════════════════════════
📊 POZİSYON BİLGİSİ
═══════════════════════════════════════════
Coin: {coin}
Giriş Fiyatı: ${entry_price:,.2f}
Şu Anki Fiyat: ${current_price:,.2f}
Kar/Zarar: %{profit_pct:.2f}

═══════════════════════════════════════════
📈 TEKNİK İNDİKATÖRLER
═══════════════════════════════════════════
RSI (14): {market['rsi']:.1f} → {market['rsi_signal']}
  • RSI < 30: Aşırı satım (yükseliş potansiyeli)
  • RSI > 70: Aşırı alım (düşüş riski)
  
MACD: {market['macd']:.2f} → {market['macd_signal']}
  • MACD > 0: Yukarı momentum
  • MACD < 0: Aşağı momentum

Trend: {market['trend']} ({market['momentum']} momentum)

Bollinger Bands:
  • Üst Band: ${market['bb_upper']:,.2f}
  • Alt Band: ${market['bb_lower']:,.2f}
  • Pozisyon: {market['bb_position']}

═══════════════════════════════════════════
📊 ORDER BOOK (Alış/Satış Emri Analizi)
═══════════════════════════════════════════
Alış Baskısı: %{market['buy_pressure']:.1f}
Satış Baskısı: %{market['sell_pressure']:.1f}
Sinyal: {market['order_book_signal']}

═══════════════════════════════════════════
💰 VOLUME ANALİZİ
═══════════════════════════════════════════
Volume Artışı: x{market['volume_spike']:.2f}
Durum: {market['volume_signal']}
Piyasa Duygusu: {market['market_sentiment']}

Son İşlem Alış/Satış Oranı: {market['buy_sell_ratio']:.2f}
  • >1.5: Güçlü alım
  • <0.7: Güçlü satım

═══════════════════════════════════════════
🎯 DESTEK/DİRENÇ SEVİYELERİ
═══════════════════════════════════════════
Destek: ${market['support']:,.2f}
Direnç: ${market['resistance']:,.2f}
Dirence Mesafe: %{market['distance_to_resistance']:.2f}

═══════════════════════════════════════════
🧠 KARAR KRİTERLERİ
═══════════════════════════════════════════
1. %0.40-%0.60 kar: Eğer RSI>70 veya MACD aşağı dönüyorsa SELL
2. %0.60-%1.50 kar: Trend ve momentum kontrol et, zayıfsa SELL
3. %1.50-%2.00 kar: Order book satış baskısı varsa SELL
4. %2.00+ kar: KAR AL! (Risk yönetimi)

ÖZEL DURUMLAR:
• RSI < 30 + Yükseliş trendi → HOLD (daha fazla kar bekle)
• Volume spike + Alış baskısı → HOLD (momentum devam edebilir)
• Bollinger üst bandına yakın + RSI > 70 → SELL (düzeltme riski)
• MACD yukarı + %1+ kar → HOLD (trend güçlü)

═══════════════════════════════════════════
📋 CEVAP FORMATI
═══════════════════════════════════════════
KARAR: SELL veya HOLD
GÜVEN: %XX (50-100 arası)
NEDENİ: Hangi teknik indikatörler ve neden?
TAHMİN: Sonraki 5 dakikada fiyat YÜKSELİR/DÜŞER/SABİT
RİSK: DÜŞÜK/ORTA/YÜKSEK"""

        response = client.models.generate_content(
            model='gemini-1.5-flash',
            contents=prompt
        )
        ai_response = response.text
        
        # Response parse et
        decision = "HOLD"
        confidence = 50
        
        if "KARAR: SELL" in ai_response or "SELL" in ai_response.split('\n')[0]:
            decision = "SELL"
        
        # Güven seviyesini çıkar
        if "GÜVEN:" in ai_response:
            try:
                conf_line = [line for line in ai_response.split('\n') if 'GÜVEN:' in line][0]
                confidence = int(''.join(filter(str.isdigit, conf_line)))
            except:
                confidence = 75
        
        return {
            'decision': decision,
            'confidence': confidence,
            'reasoning': ai_response,
            'profit_pct': profit_pct,
            'market_analysis': market
        }
        
    except Exception as e:
        print(f"[AI ERROR] {e}")
        # Fallback: basit rule-based
        profit_pct = ((current_price - entry_price) / entry_price) * 100
        if profit_pct >= 2.0:
            return {'decision': 'SELL', 'reasoning': 'Auto: %2+ kar', 'profit_pct': profit_pct, 'confidence': 100}
        elif profit_pct >= 0.50:
            return {'decision': 'SELL', 'reasoning': 'Auto: %0.5+ kar', 'profit_pct': profit_pct, 'confidence': 70}
        return {'decision': 'HOLD', 'reasoning': 'Auto: Düşük kar', 'profit_pct': profit_pct, 'confidence': 60}

