@app.route('/api/demo/trade/open', methods=['POST'])
def api_demo_trade_open():
    """Open a manual demo trade - ISOLATED from real trading"""
    if not session.get("logged_in"):
        return jsonify(ok=False, error="AUTH"), 401
    
    user_id = session.get("user_id", 0)
    data = request.get_json() or {}
    
    symbol = data.get('symbol', 'BTC/USDT')
    amount = float(data.get('amount', 0))
    side = data.get('side', 'BUY')
    
    if amount < 100:
        return jsonify(ok=False, error="Minimum 100 TL gerekli"), 400
    
    # Get demo balance
    demo_data = get_demo_balance_isolated(user_id)
    if demo_data['balance'] < amount:
        return jsonify(ok=False, error="Yetersiz demo bakiye"), 400
    
    # Fake price based on symbol
    FAKE_PRICES = {
        'BTC/USDT': 70000, 'ETH/USDT': 3500, 'SOL/USDT': 150,
        'XRP/USDT': 0.55, 'DOGE/USDT': 0.08, 'ADA/USDT': 0.45
    }
    entry_price = FAKE_PRICES.get(symbol, 100) * (1 + random.uniform(-0.01, 0.01))
    
    # Random outcome (-5% to +5%)
    pnl_percent = random.uniform(-0.05, 0.05)
    pnl = amount * pnl_percent
    exit_price = entry_price * (1 + pnl_percent)
    
    conn = db()
    # Insert trade as OPEN position (not closed yet)
    conn.execute("""
        INSERT INTO demo_trades_isolated 
        (user_id, symbol, side, amount, entry_price, exit_price, pnl, status, created_at, closed_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, 'open', CURRENT_TIMESTAMP, NULL)
    """, (user_id, symbol, side, amount, entry_price, None, 0))
    
    # Deduct from balance (money is now in position)
    new_balance = demo_data['balance'] - amount
    
    conn.execute("""
        UPDATE demo_balance_isolated 
        SET balance=?, updated_at=CURRENT_TIMESTAMP
        WHERE user_id=?
    """, (new_balance, user_id))
    
    conn.commit()
    conn.close()
    
    return jsonify(ok=True, trade={
        'symbol': symbol,
        'side': side,
        'amount': amount,
        'entry_price': entry_price,
        'status': 'open',
        'new_balance': round(new_balance, 2)
    })


# Demo Auto Trader Daemon - ISOLATED, runs fake trades
import random
import threading
import time

_demo_simulator_running = False

def demo_auto_trader_daemon():
    """
    DEMO AUTO TRADER - Completely isolated from real trading
    Makes 10-15 SPOT trades per day (BUY low, SELL high - no leverage)
    Always profitable 0.3-0.8% per trade to simulate successful spot trading
    """
    global _demo_simulator_running
    if _demo_simulator_running:
        return
    _demo_simulator_running = True
    
    # Spot trading coins with realistic prices
    COINS = {
        'BTC/USDT': {'base': 67500, 'volatility': 0.015},
        'ETH/USDT': {'base': 3450, 'volatility': 0.018},
        'SOL/USDT': {'base': 148, 'volatility': 0.025},
        'XRP/USDT': {'base': 0.52, 'volatility': 0.020},
        'DOGE/USDT': {'base': 0.078, 'volatility': 0.030},
        'ADA/USDT': {'base': 0.42, 'volatility': 0.022}
    }
    
    # Track open positions per user (spot trading: buy first, then sell)
    user_positions = {}  # {user_id: {coin: {'entry_price': X, 'amount': Y, 'bought_at': timestamp}}}
    
    def run_demo_trades():
        while True:
            try:
                # Sleep between 45-90 minutes (to make ~10-15 trades per day)
                sleep_time = random.randint(2700, 5400)  # 45-90 minutes
                time.sleep(sleep_time)
                
                # Get all users with demo accounts
                conn = db()
                users = conn.execute("SELECT DISTINCT user_id FROM demo_balance_isolated").fetchall()
                conn.close()
                
                for (user_id,) in users:
                    try:
                        demo_data = get_demo_balance_isolated(user_id)
                        balance = demo_data["balance"]
                        
                        if balance < 50:  # Not enough balance
                            continue
                        
                        # Initialize user positions if not exists
                        if user_id not in user_positions:
                            user_positions[user_id] = {}
                        
                        open_positions = user_positions[user_id]
                        
                        # Decide: BUY new coin or SELL existing position
                        coins_with_positions = list(open_positions.keys())
                        coins_without_positions = [c for c in COINS.keys() if c not in open_positions]
                        
                        action = None
                        selected_coin = None
                        
                        if coins_with_positions and random.random() > 0.4:
                            # 60% chance to SELL (close position) if we have open positions
                            action = 'SELL'
                            selected_coin = random.choice(coins_with_positions)
                        elif coins_without_positions:
                            # BUY new coin
                            action = 'BUY'
                            selected_coin = random.choice(coins_without_positions)
                        else:
                            # All positions open, must sell one
                            action = 'SELL'
                            selected_coin = random.choice(coins_with_positions)
                        
                        coin = selected_coin
                        coin_data = COINS[coin]
                        
                        # Simulate market price with realistic movement
                        price_variation = random.uniform(-coin_data['volatility'], coin_data['volatility'])
                        current_price = coin_data['base'] * (1 + price_variation)
                        
                        if action == 'BUY':
                            # SPOT BUY: Use 5-15% of balance
                            amount_usdt = balance * random.uniform(0.05, 0.15)
                            amount_usdt = round(amount_usdt, 2)
                            
                            if amount_usdt < 10:  # Minimum trade size
                                continue
                            
                            # Store position
                            open_positions[coin] = {
                                'entry_price': current_price,
                                'amount_usdt': amount_usdt,
                                'bought_at': time.time()
                            }
                            
                            print(f"[DEMO SPOT] User {user_id}: BUY {coin} @ ${current_price:,.2f} for ${amount_usdt}")
                            
                        else:  # SELL
                            if coin not in open_positions:
                                continue
                            
                            position = open_positions[coin]
                            entry_price = position['entry_price']
                            amount_usdt = position['amount_usdt']
                            
                            # Calculate profit: 0.3% to 0.8% (always positive for demo)
                            # Add some randomness based on "holding time"
                            holding_hours = (time.time() - position['bought_at']) / 3600
                            base_profit = random.uniform(0.003, 0.008)  # 0.3% - 0.8%
                            time_bonus = min(holding_hours * 0.0005, 0.005)  # Extra for longer holds
                            profit_percent = base_profit + time_bonus
                            
                            # Calculate PnL
                            pnl = amount_usdt * profit_percent
                            pnl = round(pnl, 2)
                            exit_price = entry_price * (1 + profit_percent)
                            
                            # Record the completed spot trade
                            conn = db()
                            conn.execute("""
                                INSERT INTO demo_trades_isolated 
                                (user_id, symbol, side, amount, entry_price, exit_price, pnl, status, closed_at)
                                VALUES (?, ?, 'SELL', ?, ?, ?, ?, 'closed', CURRENT_TIMESTAMP)
                            """, (user_id, coin, amount_usdt, entry_price, exit_price, pnl))
                            
                            # Update balance (add profit)
                            new_balance = balance + pnl
                            total_profit = demo_data["total_profit"] + pnl
                            total_trades = demo_data["total_trades"] + 1
                            winning_trades = demo_data["winning_trades"] + 1  # Always win in spot
                            
                            conn.execute("""
                                UPDATE demo_balance_isolated 
                                SET balance=?, total_profit=?, total_trades=?, winning_trades=?, updated_at=CURRENT_TIMESTAMP
                                WHERE user_id=?
                            """, (new_balance, total_profit, total_trades, winning_trades, user_id))
                            
                            conn.commit()
                            conn.close()
                            
                            # Remove from open positions
                            del open_positions[coin]
                            
                            print(f"[DEMO SPOT] User {user_id}: SELL {coin} @ ${exit_price:,.2f} | Profit: +${pnl} ({profit_percent*100:.2f}%)")
                        
                    except Exception as e:
                        print(f"[DEMO SPOT ERROR] User {user_id}: {e}")
                
            except Exception as e:
                print(f"[DEMO DAEMON ERROR] {e}")
                time.sleep(60)
    
    t = threading.Thread(target=run_demo_trades, name="demo_auto_trader", daemon=True)
    t.start()
    print("[DEMO TRADER] Started - Spot trading (BUY low, SELL high) ~10-15 trades/day")

# Start demo trader daemon
try:
    demo_auto_trader_daemon()
except Exception as e:
    print(f"[DEMO TRADER] Failed to start: {e}")

# ==================== END DEMO MODE ====================


# ==================== SUBSCRIPTION CHECK DAEMON ====================

_subscription_checker_running = False

def subscription_check_daemon():
    """
    Checks user subscriptions daily:
    1. Sends Telegram notification when subscription expires
    2. Disables trading for expired subscriptions
    """
    global _subscription_checker_running
    if _subscription_checker_running:
        return
    _subscription_checker_running = True
    
    def check_subscriptions():
        while True:
            try:
                # Check every hour
                time.sleep(3600)
                
                current_time = now_ts()
                conn = db()
                
                # Find users whose subscription is expiring today or expired
                # subscription_notified = 0 means not yet notified
                expiring_users = conn.execute("""
                    SELECT id, username, display_name, telegram_chat_id, subscription_type, 
                           subscription_end, subscription_active, subscription_notified
                    FROM users 
                    WHERE subscription_end <= ? AND subscription_end > 0
                """, (current_time + 86400,)).fetchall()  # Check 24 hours ahead
                
                for user in expiring_users:
                    user_id = user[0]
                    username = user[1]
                    display_name = user[2] or username
                    telegram_chat_id = user[3]
                    sub_type = user[4]
                    sub_end = user[5]
                    sub_active = user[6]
                    sub_notified = user[7]
                    
                    # Skip if already notified
                    if sub_notified:
                        # Check if subscription actually expired (past due)
                        if sub_end < current_time and sub_active:
                            # Disable trading for this user
                            conn.execute("""
                                UPDATE users SET subscription_active=0, trade_enabled=0 
                                WHERE id=?
                            """, (user_id,))
                            conn.commit()
                            print(f"[SUBSCRIPTION] Disabled trading for expired user: {username}")
                            
                            # Send final notice
                            if telegram_chat_id:
                                try:
                                    msg = f"""❌ ABONELİK SONA ERDİ

Merhaba {display_name},

Aboneliğiniz sona erdi ve işlem yapma yetkiniz askıya alındı.

Tekrar işlem yapabilmek için lütfen aboneliğinizi yenileyin:
➡️ Ödeme Yönetimi sayfasından paket seçin

Sorularınız için bizimle iletişime geçebilirsiniz.

Atalay Trade Bot"""
                                    telegram_send_to(telegram_chat_id, msg)
                                except Exception as e:
                                    print(f"[SUBSCRIPTION] Telegram send error: {e}")
                        continue
                    
                    # Subscription expiring soon - send warning
                    hours_left = (sub_end - current_time) / 3600
                    
                    if hours_left <= 24 and hours_left > 0:
                        # Expiring in 24 hours
                        if telegram_chat_id:
                            try:
                                from datetime import datetime
                                expire_date = datetime.fromtimestamp(sub_end).strftime('%d.%m.%Y %H:%M')
                                
                                msg = f"""⚠️ ABONELİK UYARISI

Merhaba {display_name},

{sub_type.upper()} paketiniz yakında sona erecek!

📅 Bitiş Tarihi: {expire_date}
⏰ Kalan Süre: ~{int(hours_left)} saat

Kesintisiz işlem yapmaya devam etmek için lütfen aboneliğinizi yenileyin:
➡️ Ödeme Yönetimi sayfasından gerekli işlemleri yapın

Atalay Trade Bot"""
                                telegram_send_to(telegram_chat_id, msg)
                                
                                # Mark as notified
                                conn.execute("UPDATE users SET subscription_notified=1 WHERE id=?", (user_id,))
                                conn.commit()
                                print(f"[SUBSCRIPTION] Sent expiry warning to: {username}")
                            except Exception as e:
                                print(f"[SUBSCRIPTION] Telegram send error: {e}")
                
                conn.close()
                
            except Exception as e:
                print(f"[SUBSCRIPTION DAEMON ERROR] {e}")
                time.sleep(300)  # Wait 5 minutes on error
    
    t = threading.Thread(target=check_subscriptions, name="subscription_checker", daemon=True)
    t.start()
    print("[SUBSCRIPTION] Checker daemon started - Checking hourly")

# Start subscription checker daemon
try:
    subscription_check_daemon()
except Exception as e:
    print(f"[SUBSCRIPTION] Failed to start checker: {e}")


# ==================== SUBSCRIPTION CHECK FUNCTION ====================

def check_user_subscription(user_id: int) -> dict:
    """
    Check if user has active subscription
    Returns: {"active": bool, "type": str, "expires_in": int (seconds), "can_trade": bool}
    """
    try:
        conn = db()
        user = conn.execute("""
            SELECT subscription_type, subscription_start, subscription_end, subscription_active, trade_enabled
            FROM users WHERE id=?
        """, (user_id,)).fetchone()
        conn.close()
        
        if not user:
            return {"active": False, "type": "none", "expires_in": 0, "can_trade": False, "message": "Kullanıcı bulunamadı"}
        
        sub_type = user[0] or "trial"
        sub_end = user[2] or 0
        sub_active = user[3]
        trade_enabled = user[4]
        
        current_time = now_ts()
        expires_in = max(0, sub_end - current_time)
        
        # Check if subscription is still valid
        is_valid = sub_end > current_time and sub_active
        
        # Trial users can only use demo mode
        can_trade_real = is_valid and trade_enabled and sub_type != "trial"
        can_trade_demo = is_valid  # Everyone can use demo during valid subscription
        
        return {
            "active": is_valid,
            "type": sub_type,
            "expires_in": expires_in,
            "expires_in_days": expires_in // 86400,
            "can_trade_real": can_trade_real,
            "can_trade_demo": can_trade_demo,
            "message": "Aktif" if is_valid else "Abonelik süresi dolmuş"
        }
    except Exception as e:
        print(f"[SUBSCRIPTION] Check error: {e}")
        return {"active": False, "type": "error", "expires_in": 0, "can_trade": False, "message": str(e)}


@app.route('/api/subscription/status')
def api_subscription_status():
    """Get current user's subscription status"""
    if not session.get("logged_in"):
        return jsonify(ok=False, error="AUTH"), 401
    
    user_id = session.get("user_id", 0)
    status = check_user_subscription(user_id)
    return jsonify(ok=True, subscription=status)


