# ==================== DEMO FAKE AUTO TRADING SCHEDULER ====================
"""
Demo Fake Trading Scheduler - Günde 10 kere otomatik fake işlem yapar
Saatler: 09:00, 10:30, 12:00, 13:30, 15:00, 16:30, 18:00, 19:30, 21:00, 22:30
Her işlem rastgele bir coin'de AL veya SAT yapar
"""

import random
import threading
import time
from datetime import datetime, timedelta

_demo_fake_trader_running = False
DEMO_FAKE_TRADE_TIMES = [
    "09:00", "10:30", "12:00", "13:30", "15:00", 
    "16:30", "18:00", "19:30", "21:00", "22:30"
]
DEMO_FAKE_COINS = ["BTC", "ETH", "SOL", "BNB", "XRP", "DOGE", "ADA", "AVAX"]

def should_run_fake_trade():
    """Check if we should run a fake trade at current time"""
    now = datetime.now()
    current_time = now.strftime("%H:%M")
    return current_time in DEMO_FAKE_TRADE_TIMES

def create_demo_fake_trade():
    """Create a single fake demo trade for active users"""
    try:
        conn = db()
        
        # Get all active users with demo mode
        users = conn.execute("""
            SELECT id, username, demo_balance 
            FROM users 
            WHERE account_mode='demo_only' OR can_use_real=0
        """).fetchall()
        
        if not users:
            # If no demo users, pick any active user
            users = conn.execute("""
                SELECT id, username, demo_balance 
                FROM users 
                WHERE demo_balance > 0
                LIMIT 5
            """).fetchall()
        
        for user in users:
            user_id = user[0]
            username = user[1]
            balance = user[2] or 10000
            
            # Random coin and side
            coin = random.choice(DEMO_FAKE_COINS)
            side = random.choice(["BUY", "SELL"])
            amount = random.choice([100, 200, 300, 500])
            
            # Fake prices
            entry_price = random.uniform(100, 50000)
            
            # Create fake position
            created_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            
            # Insert into demo_trades_isolated
            conn.execute("""
                INSERT INTO demo_trades_isolated 
                (user_id, symbol, side, amount, entry_price, pnl, status, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """, (user_id, coin, side, amount, entry_price, 0, 'open', created_at))
            
            print(f"[DEMO_FAKE] {username}: {side} {coin} @ {entry_price:.2f} | Amount: {amount}")
        
        conn.commit()
        conn.close()
        
    except Exception as e:
        print(f"[DEMO_FAKE] Error: {e}")

def demo_fake_trading_scheduler():
    """Main scheduler loop - checks every minute"""
    global _demo_fake_trader_running
    
    if _demo_fake_trader_running:
        return
    
    _demo_fake_trader_running = True
    print("[DEMO_FAKE] 🎯 Fake trading scheduler started!")
    print(f"[DEMO_FAKE] ⏰ Trade times: {', '.join(DEMO_FAKE_TRADE_TIMES)}")
    
    last_run_minute = None
    
    while True:
        try:
            now = datetime.now()
            current_minute = now.strftime("%H:%M")
            
            # Run only once per minute
            if current_minute != last_run_minute:
                last_run_minute = current_minute
                
                if current_minute in DEMO_FAKE_TRADE_TIMES:
                    print(f"[DEMO_FAKE] ⏰ Running scheduled fake trade at {current_minute}")
                    create_demo_fake_trade()
            
            # Sleep for 30 seconds to prevent high CPU usage
            time.sleep(30)
            
        except Exception as e:
            print(f"[DEMO_FAKE] Scheduler error: {e}")
            time.sleep(60)

def start_demo_fake_trading_scheduler():
    """Start the fake trading scheduler in background thread"""
    t = threading.Thread(target=demo_fake_trading_scheduler, name="demo_fake_scheduler", daemon=True)
    t.start()
    print("[DEMO_FAKE] ✅ Scheduler thread started!")

# Start the scheduler
start_demo_fake_trading_scheduler()

# ==================== END DEMO FAKE TRADING SCHEDULER ====================




