# =========================
# DEMO AUTO PNL ENGINE - Günde 15 kez %0.50 kar/zarar
# =========================

_demo_pnl_running = False
_demo_pnl_thread = None

def demo_auto_pnl_engine():
    """
    DEMO AUTO PNL ENGINE - Açık pozisyonlara otomatik kar/zarar uygular
    - Günde ~15 kez çalışır (her ~1.6 saatte bir)
    - %0.50 kar veya zarar (random)
    - Pozisyonu kapatır ve bakiyeyi günceller
    """
    global _demo_pnl_running
    print("[DEMO_PNL] Otomatik kar/zarar motoru başlatıldı")
    
    while _demo_pnl_running:
        try:
            # Her 1.6 saatte bir çalış (96 dakika) = günde ~15 kez
            time.sleep(96 * 60)
            
            conn = db()
            
            # Tüm açık demo pozisyonlarını getir
            open_trades = conn.execute(
                "SELECT id, user_id, symbol, side, amount, entry_price FROM demo_trades_isolated WHERE status='open'"
            ).fetchall()
            
            if not open_trades:
                conn.close()
                continue
            
            print(f"[DEMO_PNL] {len(open_trades)} açık pozisyon işleniyor...")
            
            for trade in open_trades:
                try:
                    trade_id, user_id, symbol, side, amount, entry_price = trade
                    
                    # %0.50 kar veya zarar (random, 60% kar olasılığı)
                    is_profit = random.random() < 0.6  # 60% kar, 40% zarar
                    pnl_percent = 0.005 if is_profit else -0.005  # %0.50
                    pnl = amount * pnl_percent
                    
                    # Yeni bakiye = eski bakiye + pozisyon tutarı + kar/zarar
                    demo_data = get_demo_balance_isolated(user_id)
                    new_balance = demo_data['balance'] + amount + pnl
                    
                    total_profit = demo_data['total_profit'] + (pnl if pnl > 0 else 0)
                    total_loss = demo_data['total_loss'] + (abs(pnl) if pnl < 0 else 0)
                    total_trades = demo_data['total_trades'] + 1
                    winning_trades = demo_data['winning_trades'] + (1 if pnl > 0 else 0)
                    
                    # Pozisyonu kapat
                    exit_price = entry_price * (1 + pnl_percent)
                    conn.execute("""
                        UPDATE demo_trades_isolated 
                        SET status='closed', pnl=?, exit_price=?, closed_at=CURRENT_TIMESTAMP
                        WHERE id=?
                    """, (round(pnl, 2), exit_price, trade_id))
                    
                    # Bakiyeyi güncelle
                    conn.execute("""
                        UPDATE demo_balance_isolated 
                        SET balance=?, total_profit=?, total_loss=?, total_trades=?, winning_trades=?, updated_at=CURRENT_TIMESTAMP
                        WHERE user_id=?
                    """, (new_balance, total_profit, total_loss, total_trades, winning_trades, user_id))
                    
                    print(f"[DEMO_PNL] Trade {trade_id}: {symbol} {'KAR' if is_profit else 'ZARAR'} {pnl:.2f} TL")
                    
                except Exception as e:
                    print(f"[DEMO_PNL] Trade işleme hatası: {e}")
                    continue
            
            conn.commit()
            conn.close()
            print(f"[DEMO_PNL] İşlem tamamlandı - {len(open_trades)} pozisyon kapatıldı")
            
        except Exception as e:
            print(f"[DEMO_PNL] Motor hatası: {e}")
            import traceback
            traceback.print_exc()

def start_demo_pnl_engine():
    """Start the demo auto PNL engine"""
    global _demo_pnl_running, _demo_pnl_thread
    if not _demo_pnl_running:
        _demo_pnl_running = True
        _demo_pnl_thread = threading.Thread(target=demo_auto_pnl_engine, daemon=True)
        _demo_pnl_thread.start()
        print("[DEMO_PNL] Motor başlatıldı - Günde 15 kez %0.50 kar/zarar")

# Motoru başlat
start_demo_pnl_engine()



