# --- 1. COPY TRADING STREAM + HEARTBEAT FIX ---
import json
from collections import deque

# Global feed değişkenleri
if 'AU_COPY_FEED' not in globals():
    AU_COPY_FEED = deque(maxlen=400)
if 'AU_COPY_LOCK' not in globals():
    AU_COPY_LOCK = __import__('threading').Lock()

def _au_feed_push(it: dict):
    """Feed'e item ekle"""
    with AU_COPY_LOCK:
        AU_COPY_FEED.appendleft(it)

@app.get("/api/copy/feed")
def api_copy_feed_fixed():
    """Copy trading feed - JSON"""
    try:
        lim = int(request.args.get("limit","60"))
    except:
        lim = 60
    with AU_COPY_LOCK:
        items = list(list(AU_COPY_FEED)[:max(1, min(400, lim))])
    return jsonify({"ok": True, "items": items})

@app.get("/api/copy/stream")
def api_copy_stream_fixed():
    """Copy trading SSE stream"""
    def gen():
        last_ts = 0
        # İlk snapshot
        with AU_COPY_LOCK:
            snap = list(list(AU_COPY_FEED)[:40])
        yield "event: snapshot\n"
        yield f"data: {json.dumps({'items': snap}, ensure_ascii=False)}\n\n"
        
        while True:
            time.sleep(1.0)
            with AU_COPY_LOCK:
                it = AU_COPY_FEED[0] if len(AU_COPY_FEED) else None
            if not it:
                continue
            ts = int(it.get("ts") or 0)
            if ts <= last_ts:
                continue
            last_ts = ts
            yield "event: tick\n"
            yield f"data: {json.dumps(it, ensure_ascii=False)}\n\n"
    return Response(gen(), mimetype="text/event-stream")

# Heartbeat üretici
def _au_copy_heartbeat_loop():
    """15 saniyede bir heartbeat gönder"""
    while True:
        time.sleep(15)
        _au_feed_push({
            "ts": int(time.time()),
            "trader": "SYSTEM",
            "event": "HEARTBEAT",
            "symbol": "-",
            "side": "-",
            "price": None,
            "size_usdt": None,
            "source": "OKX"
        })

# Heartbeat thread başlat
try:
    __import__('threading').Thread(target=_au_copy_heartbeat_loop, daemon=True).start()
except:
    pass

# --- 2. DEMO EXECUTE + AUTO MOTOR ---
import random
from datetime import datetime, timezone

# ===== AUTO COIN PACKAGE LIMIT =====
def get_auto_coin_limit(package: str) -> int:
    p = (package or "").lower()
    if "elit" in p:
        return 5
    if "premium" in p:
        return 3
    return 2
# ===== END =====


DEMO_AUTO_ENABLED = True
DEMO_AUTO_TRADES_MIN = 10
DEMO_AUTO_TRADES_MAX = 15
DEMO_AUTO_PROFIT_PCT = 0.50
DEMO_AUTO_AMOUNT = 50.0
DEMO_AUTO_SYMBOLS = ["BTC/USDT","ETH/USDT","SOL/USDT","XRP/USDT","AVAX/USDT"]

def _demo_db():
    fn = globals().get("db") or globals().get("get_db")
    if callable(fn):
        return fn()
    import sqlite3
    return sqlite3.connect("/root/backend/data.db")

def _demo_init():
    con = _demo_db()
    cur = con.cursor()
    cur.execute("""
    CREATE TABLE IF NOT EXISTS demo_state (
        id INTEGER PRIMARY KEY CHECK(id=1), 
        usdt REAL
    )""")
    cur.execute("""
    CREATE TABLE IF NOT EXISTS demo_trades (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        ts INTEGER,
        symbol TEXT,
        side TEXT,
        amount_usdt REAL,
        entry_price REAL,
        exit_price REAL,
        pnl_usdt REAL,
        status TEXT
    )""")
    cur.execute("INSERT OR IGNORE INTO demo_state(id, usdt) VALUES (1, 10000.0)")
    con.commit()

def _demo_bal():
    try:
        con = _demo_db()
        cur = con.cursor()
        cur.execute("SELECT usdt FROM demo_state WHERE id=1")
        r = cur.fetchone()
        return float(r[0]) if r and r[0] else 10000.0
    except:
        return 10000.0

def _demo_set(v):
    con = _demo_db()
    cur = con.cursor()
    cur.execute("UPDATE demo_state SET usdt=? WHERE id=1", (float(v),))
    con.commit()

def _demo_price(sym):
    base = 100.0 + (abs(hash(sym)) % 5000) / 10.0
    return round(base + random.uniform(-2.0, 2.0), 4)

def _demo_open(sym, amt):
    bal = _demo_bal()
    if bal < amt:
        return {"ok": False, "error": "DEMO yetersiz bakiye"}
    entry = _demo_price(sym)
    _demo_set(bal - amt)
    con = _demo_db()
    cur = con.cursor()
    ts = int(time.time())
    
    # Insert to demo_trades
    cur.execute("""INSERT INTO demo_trades 
        (ts, symbol, side, amount_usdt, entry_price, exit_price, pnl_usdt, status) 
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
        (ts, sym, "BUY", float(amt), float(entry), None, None, "OPEN"))
    
    # Also insert to demo_trades_isolated for dashboard display
    try:
        cur.execute("""
            CREATE TABLE IF NOT EXISTS demo_trades_isolated (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER DEFAULT 0,
                symbol TEXT,
                side TEXT,
                amount REAL,
                entry_price REAL,
                exit_price REAL,
                pnl REAL,
                status TEXT,
                created_at INTEGER
            )
        """)
        cur.execute("""
            INSERT INTO demo_trades_isolated (user_id, symbol, side, amount, entry_price, status, created_at)
            VALUES (0, ?, ?, ?, ?, 'open', ?)
        """, (sym, sym.split('/')[0] if '/' in sym else sym, float(amt), float(entry), ts))
    except Exception as e:
        print(f"[DEMO OPEN] demo_trades_isolated error: {e}")
    
    con.commit()
    return {"ok": True, "symbol": sym, "amount_usdt": amt, "entry_price": entry, "balance": _demo_bal()}

def _demo_close(sym=None):
    con = _demo_db()
    cur = con.cursor()
    if sym:
        cur.execute("SELECT id, symbol, amount_usdt, entry_price FROM demo_trades WHERE status='OPEN' AND symbol=? ORDER BY id DESC LIMIT 1", (sym,))
    else:
        cur.execute("SELECT id, symbol, amount_usdt, entry_price FROM demo_trades WHERE status='OPEN' ORDER BY id DESC LIMIT 1")
    r = cur.fetchone()
    if not r:
        return {"ok": False, "error": "Acik demo islem yok"}
    tid = r[0]
    sym = r[1] if len(r) > 1 else sym
    amt = r[2] if len(r) > 2 else 50
    entry = r[3] if len(r) > 3 else _demo_price(sym)
    
    exitp = _demo_price(sym)
    pnl = float(amt) * (DEMO_AUTO_PROFIT_PCT / 100.0)
    _demo_set(_demo_bal() + float(amt) + pnl)
    ts = int(time.time())
    
    # Update demo_trades
    cur.execute("UPDATE demo_trades SET exit_price=?, pnl_usdt=?, status='CLOSED' WHERE id=?",
                (float(exitp), float(pnl), int(tid)))
    
    # Also update demo_trades_isolated
    try:
        cur.execute("""
            UPDATE demo_trades_isolated 
            SET exit_price=?, pnl=?, status='closed', created_at=?
            WHERE symbol=? AND status='open' 
            ORDER BY id DESC LIMIT 1
        """, (float(exitp), float(pnl), ts, sym))
    except Exception as e:
        print(f"[DEMO CLOSE] demo_trades_isolated error: {e}")
    
    con.commit()
    return {"ok": True, "id": int(tid), "symbol": sym, "pnl_usdt": float(pnl), "balance": _demo_bal()}

@app.post("/api/demo/trade/execute")
def api_demo_execute_fixed():
    """Demo trade execute - Baglanti hatasi cozumu"""
    _demo_init()
    data = request.get_json(silent=True) or {}
    sym = (data.get("coin") or data.get("symbol") or "BTC/USDT").strip().upper()
    side = (data.get("side") or "BUY").strip().upper()
    amt = float(data.get("amount_usdt") or data.get("amount") or DEMO_AUTO_AMOUNT)
    
    if side == "BUY":
        return jsonify(_demo_open(sym, amt))
    return jsonify(_demo_close(sym))

# Demo auto motor - creates fake trades for all users
def _demo_auto_loop():
    _demo_init()
    import sqlite3
    import os
    
    while True:
        if not DEMO_AUTO_ENABLED:
            time.sleep(10)
            continue
        
        try:
            # Get all users
            db_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data.db')
            if not os.path.exists(db_path):
                db_path = "/root/backend/data.db"
            
            con = sqlite3.connect(db_path)
            cur = con.cursor()
            
            # Get active users
            try:
                cur.execute("SELECT id FROM users WHERE id > 0 LIMIT 50")
                users = cur.fetchall()
            except:
                users = [(0,)]  # Default user if no users table
            
            for user_row in users:
                uid = user_row[0]
                sym = random.choice(DEMO_AUTO_SYMBOLS) if DEMO_AUTO_SYMBOLS else "BTC/USDT"
                
                # Open trade for this user
                _demo_open_for_user(uid, sym, DEMO_AUTO_AMOUNT)
                time.sleep(random.randint(10, 30))
                
                # Close trade for this user
                _demo_close_for_user(uid, sym)
                time.sleep(random.randint(5, 15))
            
            con.close()
        except Exception as e:
            print(f"[DEMO AUTO LOOP ERROR] {e}")
        
        # Wait before next cycle
        time.sleep(random.randint(300, 600))  # 5-10 minutes between cycles

def _demo_open_for_user(uid, sym, amt):
    """Open demo trade for specific user"""
    try:
        import sqlite3
        import os
        db_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data.db')
        if not os.path.exists(db_path):
            db_path = "/root/backend/data.db"
        
        con = sqlite3.connect(db_path)
        cur = con.cursor()
        
        # Ensure table exists
        cur.execute("""
            CREATE TABLE IF NOT EXISTS demo_trades_isolated (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                symbol TEXT,
                side TEXT,
                amount REAL,
                entry_price REAL,
                exit_price REAL,
                pnl REAL,
                status TEXT,
                created_at INTEGER
            )
        """)
        
        bp = {"BTC/USDT":97500,"ETH/USDT":3450,"SOL/USDT":195,"XRP/USDT":2.48,"DOGE/USDT":0.335}
        entry = bp.get(sym, 100) * (1 + random.uniform(-0.02, 0.02))
        ts = int(time.time())
        
        cur.execute("""
            INSERT INTO demo_trades_isolated (user_id, symbol, side, amount, entry_price, status, created_at)
            VALUES (?, ?, ?, ?, ?, 'open', ?)
        """, (uid, sym, sym.split('/')[0] if '/' in sym else sym, float(amt), float(entry), ts))
        
        con.commit()
        con.close()
        print(f"[DEMO AUTO] Opened {sym} for user {uid}")
    except Exception as e:
        print(f"[DEMO OPEN USER ERROR] {e}")

def _demo_close_for_user(uid, sym):
    """Close demo trade for specific user"""
    try:
        import sqlite3
        import os
        db_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data.db')
        if not os.path.exists(db_path):
            db_path = "/root/backend/data.db"
        
        con = sqlite3.connect(db_path)
        cur = con.cursor()
        
        bp = {"BTC/USDT":97500,"ETH/USDT":3450,"SOL/USDT":195,"XRP/USDT":2.48,"DOGE/USDT":0.335}
        
        # Get open trade
        cur.execute("""
            SELECT id, amount, entry_price FROM demo_trades_isolated 
            WHERE user_id=? AND symbol=? AND status='open' 
            ORDER BY id DESC LIMIT 1
        """, (uid, sym))
        row = cur.fetchone()
        
        if row:
            tid, amt, entry = row
            exitp = bp.get(sym, 100) * (1 + random.uniform(-0.02, 0.02))
            pnl = (exitp - entry) / entry * amt if entry > 0 else 0
            ts = int(time.time())
            
            cur.execute("""
                UPDATE demo_trades_isolated 
                SET exit_price=?, pnl=?, status='closed', created_at=?
                WHERE id=?
            """, (float(exitp), float(pnl), ts, tid))
            
            con.commit()
            print(f"[DEMO AUTO] Closed {sym} for user {uid} with PnL {pnl:.2f}")
        
        con.close()
    except Exception as e:
        print(f"[DEMO CLOSE USER ERROR] {e}")

try:
    __import__('threading').Thread(target=_demo_auto_loop, daemon=True).start()
    print("[DEMO AUTO] Started demo auto trade loop")
except Exception as e:
    print(f"[DEMO AUTO START ERROR] {e}")

