from flask import jsonify, request

@app.get("/api/auto/coins")
def api_auto_coins():
    if not session.get("logged_in"):
        return jsonify({"ok": False}), 401
    username = session.get("username")
    conn = db()
    try:
        pending = []
        rows = conn.execute(
            "SELECT coin, exchange, created_at FROM pending_auto_trades WHERE username=?",
            (username,)
        ).fetchall()
        for r in rows:
            pending.append({"symbol": r[0], "exchange": r[1], "created_at": r[2]})
        active = []
        uid = session.get("user_id", 0)
        rows = conn.execute(
            "SELECT coin,status,created_at FROM auto_positions WHERE user_id=? AND status IN ('open','waiting')",
            (uid,)
        ).fetchall()
        for r in rows:
            active.append({"symbol": r[0], "status": r[1], "created_at": r[2]})
        return jsonify({"ok": True, "pending": pending, "active": active})
    finally:
        conn.close()

@app.post("/api/auto/coin/add")
def api_auto_coin_add():
    if not session.get("logged_in"):
        return jsonify({"ok": False}), 401
    data = request.get_json() or {}
    coin = (data.get("coin") or "").upper()
    username = session.get("username")
    user = get_user(username)
    limit_n = get_auto_coin_limit(user.get("package","temel"))
    conn = db()
    try:
        ex = conn.execute(
            "SELECT 1 FROM pending_auto_trades WHERE username=? AND UPPER(coin)=UPPER(?)",
            (username, coin)
        ).fetchone()
        if ex:
            return jsonify({"ok":False,"error":"same_coin"}),409
        cnt = count_user_auto_trades(username)
        if cnt >= limit_n:
            return jsonify({"ok":False,"error":"limit","limit":limit_n}),409
        conn.execute(
            "INSERT INTO pending_auto_trades(username,coin,exchange,created_at) VALUES(?,?,?,datetime('now'))",
            (username,coin,"OKX")
        )
        conn.commit()
        return jsonify({"ok":True})
    finally:
        conn.close()

