def generate_traders_html(traders):
    """Generate HTML for trader cards"""
    html = ""
    for i, t in enumerate(traders):
        name = t.get("name", "Trader")
        win = t.get("win", t.get("profit", "0"))
        roi = t.get("roi", "0")
        foll = t.get("followers", 0)
        html += '<div class="trader-card" data-name="' + name + '" '
        html += 'style="display:flex;justify-content:space-between;align-items:center;'
        html += 'padding:12px 16px;border-radius:10px;border:1px solid rgba(255,255,255,0.08);'
        html += 'background:#111;margin-bottom:8px;cursor:pointer;transition:all 0.2s">'
        html += '<div>'
        html += '<span style="color:#6b7280;font-weight:600;margin-right:6px">' + str(i+1) + '.</span>'
        html += '<span style="color:white;font-weight:600">' + name + '</span>'
        html += '<div style="font-size:11px;color:#6b7280;margin-top:2px">Takipci ' + str(foll) + '</div>'
        html += '</div>'
        html += '<div style="text-align:right">'
        html += '<div style="color:#22c55e;font-weight:700;font-size:14px">Win ' + str(win) + '%</div>'
        html += '<div style="font-size:11px;color:#6b7280">ROI ' + str(roi) + '%</div>'
        html += '</div></div>'
    return html

def generate_copy_traders_html(traders):
    return generate_traders_html(traders)

