@app.route('/api/ai/leverage-analysis', methods=['POST'])
def api_ai_leverage_analysis():
    """AI Kaldıraç Analizi - DETERMINISTIK (aynı coin için aynı saatte aynı sonuc)"""
    data = request.get_json(silent=True) or {}
    symbol = data.get('symbol', 'BTC/USDT')
    amount = float(data.get('amount', 100))
    
    # Baz fiyatlar
    bp = {'BTC/USDT':97500,'ETH/USDT':3450,'SOL/USDT':195,'XRP/USDT':2.48,'DOGE/USDT':0.335,'AVAX/USDT':38.5,'LINK/USDT':25.2,'ADA/USDT':0.78}
    base_price = bp.get(symbol, 100)
    
    # DETERMINISTIK ANALIZ - Aynı coin için aynı saatte aynı sonuc
    # Saat bazlı seed kullan (her saat farklı analiz, ama o saat içinde sabit)
    import hashlib
    import time
    current_hour = int(time.time() / 3600)  # Saat başı değişir
    seed_str = f"{symbol}_{current_hour}_ai_analysis_v1"
    seed = int(hashlib.md5(seed_str.encode()).hexdigest(), 16)
    
    # Sabit parametreler (seed'ten türetilmiş)
    price_change_24h = ((seed % 2000) / 100) - 10  # -10% ile +10% arası
    rsi = 30 + (seed % 40)  # 30-70 arası
    volume_trend = 0.8 + ((seed % 700) / 1000)  # 0.8-1.5 arası
    
    # Coin'e özel karakteristikler (baz coinler daha volatil)
    coin_chars = {
        'BTC/USDT': {'volatility': 0.5, 'bias': 'LONG'},
        'ETH/USDT': {'volatility': 0.7, 'bias': 'LONG'},
        'SOL/USDT': {'volatility': 1.2, 'bias': 'LONG'},
        'XRP/USDT': {'volatility': 0.8, 'bias': 'SHORT'},
        'DOGE/USDT': {'volatility': 1.5, 'bias': 'SHORT'},
    }
    char = coin_chars.get(symbol, {'volatility': 1.0, 'bias': 'LONG'})
    
    # Yön belirleme (deterministik)
    direction_seed = (seed // 1000) % 100
    if rsi < 35:
        direction = 'LONG'
        confidence = 75 + (direction_seed % 15)
        leverage_base = 7
    elif rsi > 65:
        direction = 'SHORT'
        confidence = 72 + (direction_seed % 15)
        leverage_base = 5
    elif price_change_24h > 0:
        direction = char['bias']
        confidence = 65 + (direction_seed % 15)
        leverage_base = 5 if direction == 'LONG' else 3
    else:
        direction = 'SHORT' if char['bias'] == 'LONG' else 'LONG'
        confidence = 62 + (direction_seed % 15)
        leverage_base = 3
    
    # Volatiliteye göre kaldıraç ayarı
    leverage = min(int(leverage_base * char['volatility']), 20)
    leverage = max(leverage, 2)  # Min 2x
    
    # Sabit fiyat (çok küçük sapma)
    price_variation = ((seed % 100) / 10000) - 0.005  # -0.5% ile +0.5%
    price = round(base_price * (1 + price_variation), 2)
    
    # TP/SL hesaplama (deterministik)
    rr_seed = (seed // 10000) % 100
    risk_reward = 2 + (rr_seed % 20) / 10  # 2.0 - 4.0 arası
    sl_distance = 0.015 + ((rr_seed % 15) / 1000)  # %1.5 - 3.0 arası
    
    if direction == 'LONG':
        sl = round(price * (1 - sl_distance), 2)
        tp_distance = sl_distance * risk_reward
        tp1 = round(price * (1 + tp_distance * 0.4), 2)
        tp2 = round(price * (1 + tp_distance * 0.7), 2)
        tp3 = round(price * (1 + tp_distance), 2)
    else:
        sl = round(price * (1 + sl_distance), 2)
        tp_distance = sl_distance * risk_reward
        tp1 = round(price * (1 - tp_distance * 0.4), 2)
        tp2 = round(price * (1 - tp_distance * 0.7), 2)
        tp3 = round(price * (1 - tp_distance), 2)
    
    # Risk seviyesi
    risk_level = "Düşük" if leverage <= 5 else ("Orta" if leverage <= 10 else "Yüksek")
    trend_strength = "Güçlü" if confidence > 80 else ("Orta" if confidence > 70 else "Zayıf")
    
    # Öneri metni
    recommendation = f"🎯 {symbol} için AI Analiz:\n"
    recommendation += f"📊 Yön: {direction} | Kaldıraç: {leverage}x | Güven: %{confidence}\n"
    recommendation += f"📈 RSI: {rsi} | 24s Değişim: %{price_change_24h:.2f}\n"
    recommendation += f"💡 Öneri: {'Alım' if direction == 'LONG' else 'Satış'} fırsatı. Risk: {risk_level}"
    
    from datetime import datetime
    return jsonify({
        'ok': True,
        'analysis': {
            'symbol': symbol,
            'direction': direction,
            'leverage': leverage,
            'entry_price': round(price, 2),
            'confidence': confidence,
            'tp_levels': [tp1, tp2, tp3],
            'stop_loss': sl,
            'amount': amount,
            'timestamp': datetime.now().strftime('%Y-%m-%d %H:%M'),
            'indicators': {
                'rsi': rsi,
                'price_change_24h': round(price_change_24h, 2),
                'volume_trend': round(volume_trend, 2),
                'trend_strength': trend_strength,
                'risk_level': risk_level
            },
            'recommendation': f"{direction} yönünde {leverage}x kaldıraç önerilir. Risk seviyesi: {risk_level}. Güven: %{confidence}"
        }
    })

