@app.route('/api/positions/demo/safe')
def api_positions_demo_safe_v2():
    user_id = session.get('user_id', 0)
    positions = []
    if user_id:
        try:
            conn = db()
            tables = [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()]
            if 'demo_positions' in tables:
                rows = conn.execute('SELECT * FROM demo_positions WHERE user_id=? AND status=? ORDER BY id DESC LIMIT 20', (user_id, 'open')).fetchall()
                cols = [c[1] for c in conn.execute('PRAGMA table_info(demo_positions)').fetchall()]
                for r in rows:
                    p = dict(zip(cols, r))
                    ep = float(p.get('entry_price', 0) or 0)
                    sym = p.get('symbol', 'BTC/USDT')
                    bp2 = {'BTC/USDT':97500,'ETH/USDT':3450,'SOL/USDT':195,'XRP/USDT':2.48,'DOGE/USDT':0.335}
                    cp = bp2.get(sym, ep if ep > 0 else 100) * (1 + _rnd.uniform(-0.02, 0.02))
                    amt = float(p.get('amount', 0) or 0)
                    pnl = (cp - ep) / ep * amt if ep > 0 else 0
                    pnl_pct = (cp - ep) / ep * 100 if ep > 0 else 0
                    positions.append({'id':p.get('id',0),'symbol':sym,'side':p.get('side','BUY'),'amount':amt,'entry_price':ep,'current_price':round(cp,6),'pnl':round(pnl,2),'pnl_percent':round(pnl_pct,2),'status':'open'})
            conn.close()
        except Exception as e:
            print(f'[DEMO POS] {e}')
    return jsonify({'ok': True, 'positions': positions})

