@app.route('/api/positions/demo/close', methods=['POST'])
def api_demo_position_close():
    """Demo pozisyonunu kapat ve demo_trades_isolated'a kaydet"""
    if not session.get("logged_in"):
        return jsonify({"ok":False,"error":"Giris yapin"}), 401
    try:
        data = request.get_json(silent=True) or {}
        pos_id = data.get("id")
        uid = session.get("user_id", 0)
        if not pos_id:
            return jsonify({"ok":False,"error":"ID gerekli"}), 400
        
        conn = db()
        
        # Get position details
        row = conn.execute("SELECT * FROM demo_positions WHERE id=? AND user_id=?", (pos_id, uid)).fetchone()
        if not row:
            conn.close()
            return jsonify({"ok":False,"error":"Pozisyon bulunamadi"}), 404
        
        cols = [c[1] for c in conn.execute('PRAGMA table_info(demo_positions)').fetchall()]
        pos = dict(zip(cols, row))
        
        symbol = pos.get('symbol', 'BTC/USDT')
        side = pos.get('side', 'BUY')
        amount = float(pos.get('amount', 0) or 0)
        entry_price = float(pos.get('entry_price', 0) or 0)
        
        # Calculate exit price and PnL
        bp = {"BTC/USDT":97500,"ETH/USDT":3450,"SOL/USDT":195,"XRP/USDT":2.48,"DOGE/USDT":0.335}
        exit_price = bp.get(symbol, entry_price if entry_price > 0 else 100) * (1 + _rnd.uniform(-0.01, 0.01))
        
        if side == 'BUY':
            pnl = (exit_price - entry_price) / entry_price * amount if entry_price > 0 else 0
        else:
            pnl = (entry_price - exit_price) / entry_price * amount if entry_price > 0 else 0
        
        now = int(_time.time())
        
        # Update demo_positions status
        conn.execute("""
            UPDATE demo_positions 
            SET status='closed', current_price=?, pnl=?, pnl_percent=?, closed_at=? 
            WHERE id=?
        """, (exit_price, pnl, (pnl/amount*100) if amount > 0 else 0, now, pos_id))
        
        # Insert into demo_trades_isolated for "Son Demo Islemler" display
        try:
            conn.execute("""
                INSERT INTO demo_trades_isolated 
                (user_id, symbol, side, amount, entry_price, exit_price, pnl, status, created_at) 
                VALUES (?,?,?,?,?,?,?,?,?)
            """, (uid, symbol, side, amount, entry_price, exit_price, pnl, 'closed', now))
        except Exception as e:
            # Table might not exist, create it
            conn.execute("""
                CREATE TABLE IF NOT EXISTS demo_trades_isolated (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id INTEGER,
                    symbol TEXT,
                    side TEXT,
                    amount REAL,
                    entry_price REAL,
                    exit_price REAL,
                    pnl REAL,
                    status TEXT,
                    created_at INTEGER
                )
            """)
            conn.execute("""
                INSERT INTO demo_trades_isolated 
                (user_id, symbol, side, amount, entry_price, exit_price, pnl, status, created_at) 
                VALUES (?,?,?,?,?,?,?,?,?)
            """, (uid, symbol, side, amount, entry_price, exit_price, pnl, 'closed', now))
        
        conn.commit()
        conn.close()
        
        return jsonify({
            "ok": True, 
            "message": f"{symbol} pozisyonu kapandi (PnL: {pnl:+.2f} TL)",
            "pnl": pnl,
            "exit_price": exit_price
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({"ok":False,"error":str(e)}), 500

