@app.route('/api/demo/trades')
def api_demo_trades_list():
    """Son demo işlemlerini getir (demo_trades_isolated)"""
    if not session.get('logged_in'):
        return jsonify({'ok':False,'error':'LOGIN'}), 401
    uid = session.get('user_id', 0)
    try:
        import sqlite3
        import os
        
        db_path = "/root/backend/data.db"
        
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        
        # Ensure table exists
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS demo_trades_isolated (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER DEFAULT 0,
                symbol TEXT,
                side TEXT,
                amount REAL,
                entry_price REAL,
                exit_price REAL,
                pnl REAL,
                status TEXT,
                created_at INTEGER
            )
        """)
        conn.commit()
        
        # Fetch trades
        cursor.execute(
            "SELECT id, symbol, side, amount, entry_price, exit_price, pnl, status, created_at FROM demo_trades_isolated WHERE user_id=? OR user_id=0 ORDER BY created_at DESC LIMIT 20",
            (uid,)
        )
        rows = cursor.fetchall()
        
        trades = []
        import time
        for r in rows:
            ts = r[8] or 0
            # Safe timestamp formatting
            try:
                if ts and ts > 0:
                    time_str = time.strftime('%Y-%m-%d %H:%M', time.localtime(ts))
                else:
                    time_str = '-'
            except:
                time_str = '-'
            
            trades.append({
                'id': r[0],
                'symbol': r[1] or '',
                'side': r[2] or 'BUY',
                'amount': r[3] or 0,
                'entry_price': r[4] or 0,
                'exit_price': r[5] or 0,
                'pnl': r[6] or 0,
                'status': r[7] or 'open',
                'created_at': ts,
                'created_at_formatted': time_str
            })
        
        conn.close()
        return jsonify({'ok': True, 'trades': trades, 'count': len(trades)})
    except Exception as e:
        import traceback
        error_msg = f"[DEMO TRADES ERROR] {str(e)}"
        print(error_msg)
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e), 'traceback': traceback.format_exc()}), 500

