@app.route('/api/copy/positions')
def api_copy_positions_enhanced():
    uc = request.args.get('uc', '')
    if not uc:
        return jsonify({'ok': True, 'positions': []})
    
    # TRY TO GET REAL DATA FROM OKX API
    try:
        res = _okx_get("/api/v5/copytrading/current-subpositions", {
            "instType": "SWAP",
            "uniqueCode": uc,
            "subPosType": "lead",
        })
        j = res.get("json") or {}
        data = j.get("data") or []
        
        if isinstance(data, list) and len(data) > 0:
            positions = []
            for pos in data:
                try:
                    inst_id = pos.get("instId", "")
                    side = pos.get("posSide", "LONG")
                    entry_px = float(pos.get("openAvgPx", 0) or pos.get("avgPx", 0) or 0)
                    sz = float(pos.get("sz", 0) or 0)
                    leverage = pos.get("lever", "10")
                    mark_px = float(pos.get("markPx", entry_px) or entry_px)
                    
                    # Calculate PnL
                    if side == "LONG":
                        pnl_pct = (mark_px - entry_px) / entry_px * 100 * float(leverage) if entry_px > 0 else 0
                    else:
                        pnl_pct = (entry_px - mark_px) / entry_px * 100 * float(leverage) if entry_px > 0 else 0
                    
                    positions.append({
                        'symbol': inst_id,
                        'side': side,
                        'leverage': str(leverage) + 'x',
                        'entry_price': round(entry_px, 4),
                        'current_price': round(mark_px, 4),
                        'size_usdt': round(sz * entry_px, 2),
                        'pnl': round(sz * entry_px * pnl_pct / 100, 2),
                        'pnl_pct': round(pnl_pct, 2),
                        'exchange': 'OKX'
                    })
                except:
                    continue
            
            if positions:
                return jsonify({'ok': True, 'positions': positions, 'source': 'okx_api'})
    except Exception as e:
        print(f"[COPY POSITIONS] OKX API error: {e}")
    
    # FALLBACK: Use cached positions if API fails
    return jsonify({'ok': True, 'positions': [], 'message': 'No open positions found for this trader'})

@app.route('/api/copy/manual_buy', methods=['POST'])
def api_copy_manual_buy_v2():
    if not session.get('logged_in'): return jsonify({'ok':False,'error':'LOGIN'}), 401
    data = request.get_json(silent=True) or {}
    symbol = data.get('symbol', 'BTC/USDT')
    amount = float(data.get('amount_usdt', 100))
    price = float(data.get('price', 0))
    side = data.get('side', 'LONG')
    uid = session.get('user_id', 0)
    try:
        conn = db()
        cursor = conn.cursor()
        
        # Check if table exists and get its columns
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='real_positions'")
        table_exists = cursor.fetchone()
        
        if not table_exists:
            # Create new table with symbol column
            cursor.execute('''
                CREATE TABLE real_positions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id INTEGER,
                    symbol TEXT,
                    coin TEXT,
                    side TEXT,
                    amount REAL,
                    entry_price REAL,
                    current_price REAL,
                    pnl REAL DEFAULT 0,
                    pnl_percent REAL DEFAULT 0,
                    leverage TEXT DEFAULT '1x',
                    source TEXT DEFAULT 'manual',
                    status TEXT DEFAULT 'open',
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            ''')
        else:
            # Check if symbol column exists
            cursor.execute("PRAGMA table_info(real_positions)")
            columns = [col[1] for col in cursor.fetchall()]
            if 'symbol' not in columns:
                # Add symbol column
                cursor.execute("ALTER TABLE real_positions ADD COLUMN symbol TEXT")
            if 'coin' not in columns:
                cursor.execute("ALTER TABLE real_positions ADD COLUMN coin TEXT")
        
        buy_side = 'BUY' if side == 'LONG' else 'SELL'
        coin = symbol.split('/')[0] if '/' in symbol else symbol
        
        cursor.execute('''
            INSERT INTO real_positions (user_id, symbol, coin, side, amount, entry_price, current_price, source, status) 
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        ''', (uid, symbol, coin, buy_side, amount, price, price, 'copy_trade', 'open'))
        
        conn.commit()
        conn.close()
        return jsonify({'ok': True, 'message': symbol + ' ' + str(amount) + ' USDT $' + str(price) + ' fiyatindan alindi!'})
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500

